// Cyrus mods on ONE server: what the Mods tab shows next to a Cyrus row
// (installed version, newer version, history with notes) and the pre-engine
// builder installs it can start tracking. Server-only (DB), no next/* imports.
import type { ModBuild } from "@prisma/client";
import { db } from "../db";
import { CYRUS_SOURCE } from "../mods/installers/cyrus";
import { buildModDoc, currentVersion, succeededVersions, versionLabel } from "./doc";
import { packageVersionFor } from "./registry";

export type CyrusRowInfo = {
  rootBuildId: string;
  /** The build on the server now (ServerMod.versionId), when known. */
  installedBuildId: string | null;
  installedLabel: string | null;
  /** The chain's current version (the creator's restored head, else the newest). */
  latestBuildId: string;
  latestLabel: string;
  /** Package version string of the latest (what ServerMod.version would read after updating). */
  latestPackageVersion: string;
  updateAvailable: boolean;
  versionCount: number;
  /** NxLabs page slug (the page exists for every finished chain). */
  pageSlug: string | null;
};

export type CyrusVersionRow = {
  buildId: string;
  label: string;
  version: string | null;
  mcVersion: string;
  at: string;
  notes: string;
  request: string;
  installed: boolean;
  latest: boolean;
  safety: "pass" | "warn" | "block" | null;
};

async function chainsFor(roots: string[]): Promise<Map<string, ModBuild[]>> {
  const rows = roots.length ? await db.modBuild.findMany({ where: { OR: [{ id: { in: roots } }, { rootBuildId: { in: roots } }] }, orderBy: { createdAt: "asc" } }) : [];
  const out = new Map<string, ModBuild[]>();
  for (const b of rows) {
    const r = b.rootBuildId ?? b.id;
    out.set(r, [...(out.get(r) ?? []), b]);
  }
  return out;
}

/** Per-ServerMod Cyrus facts for the rows that are Cyrus mods (keyed by GameMod id). */
export async function cyrusInfoForRows(rows: { modId: string; versionId: string | null; mod: { source: string; sourceId: string | null } }[]): Promise<Map<string, CyrusRowInfo>> {
  const cy = rows.filter((r) => r.mod.source === CYRUS_SOURCE && r.mod.sourceId);
  const out = new Map<string, CyrusRowInfo>();
  if (!cy.length) return out;
  const roots = [...new Set(cy.map((r) => r.mod.sourceId!))];
  const [chains, pages] = await Promise.all([
    chainsFor(roots),
    db.cyrusModPage.findMany({ where: { rootBuildId: { in: roots } }, select: { rootBuildId: true, slug: true } }),
  ]);
  for (const r of cy) {
    const chain = chains.get(r.mod.sourceId!) ?? [];
    const ok = succeededVersions(chain);
    const cur = currentVersion(chain);
    if (!cur) continue;
    const idx = (id: string | null) => ok.findIndex((b) => b.id === id);
    const label = (id: string | null) => {
      const i = idx(id);
      return i < 0 ? null : versionLabel({ n: i + 1, version: ok[i].version });
    };
    out.set(r.modId, {
      rootBuildId: r.mod.sourceId!,
      installedBuildId: r.versionId,
      installedLabel: label(r.versionId),
      latestBuildId: cur.id,
      latestLabel: label(cur.id) ?? "latest",
      latestPackageVersion: packageVersionFor(cur, chain),
      updateAvailable: !!r.versionId && r.versionId !== cur.id,
      versionCount: ok.length,
      pageSlug: pages.find((p) => p.rootBuildId === r.mod.sourceId)?.slug ?? null,
    });
  }
  return out;
}

/** Version history of a Cyrus mod with release notes, newest first, marked against what's on the server. */
export async function cyrusVersionHistory(rootBuildId: string, installedBuildId: string | null): Promise<CyrusVersionRow[]> {
  const chain = (await chainsFor([rootBuildId])).get(rootBuildId) ?? [];
  const doc = buildModDoc(chain);
  if (!doc) return [];
  return doc.versions.map((v) => ({
    buildId: v.buildId,
    label: versionLabel(v),
    version: v.version,
    mcVersion: v.mcVersion,
    at: v.at,
    notes: v.notes,
    request: v.request,
    installed: v.buildId === installedBuildId,
    latest: v.buildId === doc.currentBuildId,
    safety: v.safety,
  }));
}

export type UntrackedCyrus = { buildId: string; name: string; version: string | null; at: string };

/**
 * Builds a pre-engine builder install put on this server that the Mods tab
 * can't manage yet (no ServerMod row): newest per chain.
 */
export async function untrackedCyrusInstalls(serverId: string, userId: string): Promise<UntrackedCyrus[]> {
  const builds = await db.modBuild.findMany({ where: { userId, status: "succeeded" }, orderBy: { createdAt: "desc" }, take: 200 });
  const here = builds.filter((b) => (b.lastInstall as { serverId?: string } | null)?.serverId === serverId);
  if (!here.length) return [];
  const tracked = new Set(
    (await db.serverMod.findMany({ where: { serverId, mod: { source: CYRUS_SOURCE } }, select: { mod: { select: { sourceId: true } } } })).map((r) => r.mod.sourceId),
  );
  const seen = new Set<string>();
  const out: UntrackedCyrus[] = [];
  for (const b of here) {
    const root = b.rootBuildId ?? b.id;
    if (tracked.has(root) || seen.has(root)) continue;
    seen.add(root);
    out.push({ buildId: b.id, name: b.pluginName ?? "Cyrus mod", version: b.version, at: ((b.lastInstall as { at?: string }).at ?? b.createdAt.toISOString()) });
  }
  return out;
}
"use server";

/**
 * Mods tab → Cyrus mods on one server: version history with notes, switch to
 * the latest or any earlier version (rollback), and start tracking a jar an
 * older builder install left on the server.
 *
 * Every switch is the normal engine path: ServerMod → UPDATING with
 * targetVersionId = the chosen build, one GAME_MOD_SYNC job under the per-server
 * lock (lib/mods/queue.ts). The engine backs up the jar it replaces.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { familyFor } from "./game-config";
import { SANDBOX } from "./sandbox";
import { enqueueModOp } from "./mods/queue";
import { CYRUS_SOURCE } from "./mods/installers/cyrus";
import { cyrusVersionHistory, type CyrusVersionRow } from "./cyrus-mods/installed";
import { installBuildToServer } from "./modbuilder/install";
import { cyrusAccessFor } from "./cyrus-mods/gate";

async function ownedCyrusRow(serverId: string, modId: string) {
  const user = await requireUser();
  if (typeof serverId !== "string" || serverId.length > 64 || typeof modId !== "string" || modId.length > 64) throw new Error("Not found");
  const server = await db.server.findUnique({ where: { id: serverId }, include: { osTemplate: true, gamePlan: true } });
  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) throw new Error("Not found");
  const row = await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId } }, include: { mod: true } });
  if (!row || row.mod.source !== CYRUS_SOURCE || !row.mod.sourceId) throw new Error("Not found");
  return { user, server, row, rootBuildId: row.mod.sourceId };
}

export async function getCyrusVersions(serverId: string, modId: string): Promise<{ error?: string; name?: string; status?: string; versions?: CyrusVersionRow[]; pageHref?: string | null; canSwitch?: boolean; why?: string | null }> {
  try {
    const { user, server, row, rootBuildId } = await ownedCyrusRow(serverId, modId);
    const versions = await cyrusVersionHistory(rootBuildId, row.versionId);
    const page = await db.cyrusModPage.findUnique({ where: { rootBuildId }, select: { slug: true } });
    const access = await cyrusAccessFor(user);
    const why = row.status !== "INSTALLED" ? (row.status === "DISABLED" ? "Switch it on first to change its version." : "Wait for the current change to finish.")
      : server.status !== "RUNNING" ? "Start the server to change versions."
      : null;
    return { name: row.mod.name, status: row.status, versions, pageHref: page && access.allowed ? `/dashboard/nxlabs/cyrus/${page.slug}` : null, canSwitch: !why, why };
  } catch {
    return { error: "Couldn't load this mod's versions." };
  }
}

export async function switchCyrusVersion(serverId: string, modId: string, buildId: string): Promise<{ ok?: true; error?: string; jobId?: string }> {
  let ctx;
  try {
    ctx = await ownedCyrusRow(serverId, modId);
  } catch {
    return { error: "Not found." };
  }
  const { user, server, row, rootBuildId } = ctx;
  if (familyFor(server) !== "minecraft") return { error: "Not found." };
  if (server.status !== "RUNNING") return { error: "Start the server's VM first — mods are changed on the running server." };
  if (!SANDBOX && process.env.ENABLE_REAL_GAMEMODS !== "1") return { error: "One-click mod changes are paused right now, so nothing was queued." };
  if (row.status !== "INSTALLED") return { error: row.status === "DISABLED" ? `${row.mod.name} is switched off — switch it on first.` : `${row.mod.name} is busy right now.` };
  if (typeof buildId !== "string" || !/^[A-Za-z0-9_-]{1,64}$/.test(buildId)) return { error: "Pick a version." };
  if (row.versionId === buildId) return { error: "That version is already on the server." };
  const b = await db.modBuild.findUnique({ where: { id: buildId } });
  if (!b || (b.rootBuildId ?? b.id) !== rootBuildId || b.status !== "succeeded" || !b.jarPath) return { error: "That isn't a finished version of this mod." };
  if (b.userId !== server.userId) return { error: "Not found." };
  const r = await enqueueModOp(serverId, modId, "update", { userId: user.id, slug: row.mod.slug }, { targetVersionId: buildId });
  if (!r.ok) return { error: r.error };
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true, jobId: r.jobId };
}

/** Bring a pre-engine builder install under the Mods tab (re-installs the same build through the engine). */
export async function trackCyrusInstall(serverId: string, buildId: string): Promise<{ ok?: true; error?: string }> {
  const user = await requireUser();
  if (typeof buildId !== "string" || buildId.length > 64 || typeof serverId !== "string" || serverId.length > 64) return { error: "Not found." };
  const b = await db.modBuild.findUnique({ where: { id: buildId } });
  if (!b || b.userId !== user.id) return { error: "Not found." };
  const r = await installBuildToServer(b, user.id, serverId, { waitMs: 0 });
  if (!r.ok) return { error: r.error };
  await db.auditLog.create({ data: { userId: user.id, action: "modbuilder.track", detail: `${b.id} -> ${serverId}` } }).catch(() => {});
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true };
}
// Install a finished Cyrus / Mod Builder build onto one of the user's Minecraft servers.
//
// Since 2026-10-07 (Cyrus mods) this goes THROUGH THE MODS ENGINE instead of a
// direct copy: the build's chain gets a GameMod row (source "cyrus",
// lib/cyrus-mods/registry.ts), the ServerMod row is queued INSTALLING/UPDATING
// with targetVersionId = this build, and the worker's GAME_MOD_SYNC places the
// jar with lib/mods/engine.ts (state file, backup, staged write, rollback). So
// the Mods tab lists it, can switch it off/on, update it, roll it back and
// uninstall it like any other plugin.
//
// A jar a PRE-ENGINE builder install left in plugins/ (not in the engine's state
// file) is backed up to /root/.nxeon-mods/backups/<stamp>-cyrus-adopt-<name>/
// and removed first, so the server never loads two copies of one plugin.
// The route then waits briefly for the job so the Cyrus UI can say "done".
import type { ModBuild } from "@prisma/client";
import { enqueueModOp } from "../mods/queue";
import { loadState, ownerOf } from "../mods/engine";
import { ensureCyrusGameMod, loadChain, rootOf } from "../cyrus-mods/registry";
import { syncCyrusModPage } from "../cyrus-mods/pages";
import { db } from "../db";
import { SANDBOX } from "../sandbox";
import { familyFor } from "../game-config";
import { LocalGuestFs, sandboxGuestRoot, seedSandboxGuest, type GuestFs } from "../mods/guest-fs";
import { SshGuestFs } from "../../worker/mods-guest-ssh";

const MC_BASE = "/opt/mc";
const PLUGINS = `${MC_BASE}/plugins`;
const BACKUPS = "/root/.nxeon-mods/backups";
/** Generated plugins target the Paper API (Adventure etc.), so Spigot/Bukkit can't load them, and they aren't Folia-safe. */
export const MB_INSTALL_VARIANTS = ["paper", "purpur"];

export type MbServer = { id: string; name: string; variant: string | null; status: string; compatible: boolean; reason?: string };

/** The user's Minecraft servers, each marked whether a builder plugin can go on it. */
export async function modBuilderServers(userId: string): Promise<MbServer[]> {
  const rows = await db.server.findMany({
    where: { userId, status: { notIn: ["DELETING"] } },
    include: { osTemplate: true, gamePlan: true },
    orderBy: { createdAt: "asc" },
  });
  const out: MbServer[] = [];
  for (const s of rows) {
    if (familyFor(s) !== "minecraft") continue;
    const variant = (s.gameVariant || "vanilla").toLowerCase();
    const okVariant = MB_INSTALL_VARIANTS.includes(variant);
    // The engine installs onto the running server (same rule as the Mods tab).
    const okStatus = s.status === "RUNNING";
    out.push({
      id: s.id,
      name: s.label || s.hostname,
      variant,
      status: s.status,
      compatible: okVariant && okStatus,
      reason: !okVariant ? `Runs ${variant[0].toUpperCase() + variant.slice(1)}; plugins need Paper or Purpur` : !okStatus ? (s.status === "STOPPED" ? "Server is stopped — start it to install" : `Server is ${s.status.toLowerCase()}`) : undefined,
    });
  }
  return out;
}

function stamp(d = new Date()) {
  return d.toISOString().replace(/[-:]/g, "").replace(/\..+$/, "").replace("T", "-");
}

export type InstallResult =
  | { ok: true; path: string; replaced: string[]; backupDir: string | null; serverName: string; queued: boolean; jobId: string; modId: string }
  | { ok: false; error: string };

/**
 * Move aside jars an older (pre-engine) builder install left in plugins/: only
 * files the engine's state file does NOT own, named like this plugin. Backed up
 * first. Returns what was moved.
 */
async function adoptLegacyJars(server: Parameters<typeof SshGuestFs.open>[0] & { id: string; gameVariant: string | null }, chain: ModBuild[]): Promise<{ moved: string[]; backupDir: string | null }> {
  let fs: GuestFs;
  let ssh: SshGuestFs | null = null;
  try {
    if (SANDBOX) {
      const local = new LocalGuestFs(sandboxGuestRoot(server.id));
      await seedSandboxGuest(local, "minecraft", server.gameVariant ?? null);
      fs = local;
    } else {
      ssh = await SshGuestFs.open(server);
      fs = ssh;
    }
    if (!(await fs.stat(PLUGINS))) return { moved: [], backupDir: null };
    const state = await loadState(fs, "minecraft");
    const names = new Set(chain.map((b) => (b.pluginName ?? "").toLowerCase()).filter(Boolean));
    const jars = new Set(chain.map((b) => (b.jarName ?? "").toLowerCase()).filter(Boolean));
    const legacy = (await fs.list(PLUGINS)).filter((f) => {
      const l = f.toLowerCase();
      if (!l.endsWith(".jar") || ownerOf(state, `${PLUGINS}/${f}`)) return false;
      return jars.has(l) || [...names].some((n) => l === `${n}.jar` || (l.startsWith(`${n}-`) && /^[0-9]/.test(l.slice(n.length + 1))));
    });
    if (!legacy.length) return { moved: [], backupDir: null };
    const label = (chain[0].pluginName ?? "plugin").replace(/[^A-Za-z0-9_]/g, "") || "plugin";
    const backupDir = `${BACKUPS}/${stamp()}-cyrus-adopt-${label}`;
    for (const f of legacy) await fs.copy(`${PLUGINS}/${f}`, `${backupDir}${PLUGINS}/${f}`);
    for (const f of legacy) await fs.remove(`${PLUGINS}/${f}`);
    return { moved: legacy, backupDir };
  } finally {
    ssh?.close();
  }
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

export async function installBuildToServer(build: ModBuild, userId: string, serverId: string, opts: { waitMs?: number } = {}): Promise<InstallResult> {
  if (build.userId !== userId) return { ok: false, error: "Not found." };
  if (build.status !== "succeeded" || !build.jarName || !build.pluginName) return { ok: false, error: "This build has no plugin file to install." };
  const server = await db.server.findUnique({ where: { id: serverId }, include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true } });
  if (!server || server.userId !== userId) return { ok: false, error: "Server not found." };
  const servers = await modBuilderServers(userId);
  const facts = servers.find((s) => s.id === serverId);
  if (!facts) return { ok: false, error: "That server isn't a Minecraft server." };
  if (!facts.compatible) return { ok: false, error: facts.reason || "That server can't take this plugin." };
  if (!SANDBOX && process.env.ENABLE_REAL_GAMEMODS !== "1") return { ok: false, error: "One-click mod changes are paused right now, so nothing was installed." };

  const root = rootOf(build);
  const chain = await loadChain(root);
  await syncCyrusModPage(root);
  const gm = await ensureCyrusGameMod(root, chain);
  if (!gm) return { ok: false, error: "This build has no plugin file to install." };

  const existing = await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId: gm.id } } });
  if (existing?.status === "DISABLED") return { ok: false, error: `${gm.name} is switched off on ${facts.name}. Switch it on in the server's Mods tab first, then install this version.` };
  if (existing && !["INSTALLED", "FAILED", "REMOVED"].includes(existing.status)) return { ok: false, error: `${gm.name} is busy on that server (${existing.status.toLowerCase()}). Try again in a moment.` };
  if (existing?.status === "INSTALLED" && existing.versionId === build.id) {
    return { ok: true, path: `${PLUGINS}/${build.jarName}`, replaced: [], backupDir: null, serverName: facts.name, queued: false, jobId: "", modId: gm.id };
  }
  const op = existing?.status === "INSTALLED" ? "update" : "install";

  // First engine install on a server an older builder install already used: adopt its jar.
  let adopted: { moved: string[]; backupDir: string | null } = { moved: [], backupDir: null };
  const touched = chain.some((b) => (b.lastInstall as { serverId?: string } | null)?.serverId === serverId);
  if (op === "install" && touched) {
    try {
      adopted = await adoptLegacyJars(server, chain);
    } catch (e) {
      console.error("[modbuilder] legacy adopt failed", build.id, serverId, (e as Error).message);
      return { ok: false, error: "We couldn't reach the server to check its plugins folder. Check it's online and try again." };
    }
  }

  const prevVersion = existing?.status === "INSTALLED" ? existing.version : null;
  const q = await enqueueModOp(serverId, gm.id, op, { userId, slug: gm.slug }, { targetVersionId: build.id });
  if (!q.ok) return { ok: false, error: q.error };

  // Wait (briefly) for the worker so the builder UI can report the outcome.
  const deadline = Date.now() + (opts.waitMs ?? 45_000);
  while (Date.now() < deadline) {
    await sleep(1000);
    const job = await db.job.findUnique({ where: { id: q.jobId }, select: { status: true, error: true } });
    if (!job || job.status === "QUEUED" || job.status === "RUNNING") continue;
    const sm = await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId: gm.id } } });
    if (job.status === "FAILED") return { ok: false, error: sm?.error || "The install job failed. Check the server's Mods tab." };
    if (!sm || sm.status === "FAILED" || sm.versionId !== build.id) return { ok: false, error: sm?.error || "The plugin wasn't installed. Check the server's Mods tab." };
    return {
      ok: true,
      path: `${PLUGINS}/${build.jarName}`,
      replaced: [...adopted.moved, ...(prevVersion ? [`${gm.name} ${prevVersion}`] : [])],
      backupDir: adopted.backupDir,
      serverName: facts.name,
      queued: false,
      jobId: q.jobId,
      modId: gm.id,
    };
  }
  return { ok: true, path: `${PLUGINS}/${build.jarName}`, replaced: adopted.moved, backupDir: adopted.backupDir, serverName: facts.name, queued: true, jobId: q.jobId, modId: gm.id };
}

/**
 * Mod health after a game restart / update (prd-004; lib/mod-health.ts holds the
 * logic). Registered on the SweepRunner as "mod-health" (worker/index.ts).
 *
 * INERT unless ENABLE_MOD_HEALTH=1. Reading a log is harmless, but the actions
 * it can take are not, so each has its own switch and its own guards:
 *
 *   ENABLE_MOD_HEALTH=1        check + record + notify (read-only on the server)
 *   MOD_HEALTH_AUTORESTART=0   turn the one safe restart off (default on, within the flag)
 *   MOD_HEALTH_AUTOPAUSE=1     pause a mod with POSITIVE error evidence (needs ENABLE_REAL_GAMEMODS=1)
 *   MOD_HEALTH=off             kill switch
 *
 * When it checks: a server whose game process started (GameRuntime.startedAt,
 * the fleet probe) more than 4 minutes ago and whose start has not been checked
 * yet. That covers a Steam/game update restart, a crash restart, a customer
 * restart and a mod install, with no extra bookkeeping on the update path.
 *
 * Guards (restart): the server must have ZERO players counted (null = unknown =
 * no restart), at most one auto-restart per server per 6 hours, never while any
 * job is queued/running, and never for a mod that merely wasn't seen AND has an
 * error elsewhere (that needs a human). A server with players only gets a notice.
 */
import type { Job } from "@prisma/client";
import { db } from "../lib/db";
import { familyFor } from "../lib/game-config";
import { withServerSsh, exec as sshExec } from "../lib/ssh-exec";
import { healthSupported, judgeModHealth, decideHealthAction, healthSummary, type HealthMod } from "../lib/mod-health";
import { dockerContainerNameFrom } from "./game-variant";
import { enqueueModOp } from "../lib/mods/queue";
import { playersOnline } from "./mod-autoupdate";
import { toggleDecision } from "../lib/mods/toggle-policy";
import { engineInstallerFor } from "../lib/mods/installers";

const SETTLE_MS = 4 * 60_000;
const RESTART_COOLDOWN_MS = 6 * 3600_000;
const PER_SWEEP = 5;
const CONTAINER_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,62}$/;

export const modHealthConfig = (env: NodeJS.ProcessEnv = process.env) => ({
  enabled: env.ENABLE_MOD_HEALTH === "1" && env.MOD_HEALTH !== "off",
  autoRestart: env.MOD_HEALTH_AUTORESTART !== "0",
  autoPause: env.MOD_HEALTH_AUTOPAUSE === "1" && env.ENABLE_REAL_GAMEMODS === "1",
});

let running = false;

export async function modHealthSweep(): Promise<{ checked: number }> {
  const cfg = modHealthConfig();
  if (!cfg.enabled || running) return { checked: 0 };
  running = true;
  let checked = 0;
  try {
    const servers = await db.server.findMany({
      where: { status: "RUNNING", mods: { some: { status: "INSTALLED" } }, gameRuntime: { state: "online", startedAt: { not: null, lt: new Date(Date.now() - SETTLE_MS) } } },
      include: {
        osTemplate: true,
        gamePlan: true,
        node: true,
        dedicatedIp: true,
        gameRuntime: { select: { startedAt: true, intent: true } },
        mods: { where: { status: "INSTALLED" }, include: { mod: { select: { name: true, sourceId: true } } } },
      },
      take: 400,
    });
    for (const s of servers) {
      if (checked >= PER_SWEEP) break;
      const family = familyFor(s);
      if (!family || !healthSupported(family, s.gameVariant ?? null)) continue;
      if (s.gameRuntime?.intent === "stopped") continue;
      const startedAt = s.gameRuntime!.startedAt!;
      const last = await db.modUpdateRun.findFirst({ where: { serverId: s.id, trigger: "health" }, orderBy: { startedAt: "desc" }, select: { plan: true } });
      if (((last?.plan ?? {}) as { startedAt?: string }).startedAt === startedAt.toISOString()) continue;
      if ((await db.job.count({ where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } } })) > 0) continue;
      checked++;
      try {
        await checkOne(s as unknown as Loaded, family, startedAt, cfg);
      } catch (e) {
        console.error(`[mod-health] ${s.hostname}:`, (e as Error).message);
        // Record the attempt so a server we cannot read is not retried every sweep.
        await db.modUpdateRun.create({ data: { serverId: s.id, trigger: "health", status: "NOOP", summary: "Couldn't read the server's log to check its mods.", plan: { startedAt: startedAt.toISOString() }, finishedAt: new Date() } }).catch(() => {});
      }
    }
  } finally {
    running = false;
  }
  return { checked };
}

type Loaded = {
  id: string; userId: string; hostname: string; gameVariant: string | null;
  osTemplate: { name: string; setupScript: string | null };
  mods: { mod: { name: string; sourceId: string | null }; fileName: string | null }[];
};

async function readLog(server: Loaded, since: Date): Promise<string> {
  const container = dockerContainerNameFrom(server.osTemplate.setupScript ?? "");
  if (!container || !CONTAINER_RE.test(container)) throw new Error("no container name");
  const cmd = `docker logs --since ${since.toISOString()} ${container} 2>&1 | tail -n 4000`;
  const r = await withServerSsh(server as never, (conn) => sshExec(conn, cmd, 30_000));
  return r.stdout;
}

async function checkOne(server: Loaded, family: string, startedAt: Date, cfg: ReturnType<typeof modHealthConfig>) {
  const log = await readLog(server, startedAt);
  const mods: HealthMod[] = server.mods.map((m) => ({ name: m.mod.name, key: m.mod.sourceId ?? m.mod.name, fileName: m.fileName }));
  const report = judgeModHealth({ family, variant: server.gameVariant, mods, log });
  const players = await playersOnline(server.id, family);
  const recentRestart = await db.modUpdateRun.findFirst({
    where: { serverId: server.id, trigger: "health", status: "HEALTH_RESTARTED", startedAt: { gt: new Date(Date.now() - RESTART_COOLDOWN_MS) } },
    select: { id: true },
  });
  const action = decideHealthAction({ report, playersOnline: players, alreadyRestartedForThisStart: !!recentRestart, autoPause: cfg.autoPause, autoRestart: cfg.autoRestart });

  let status = report.overall === "ok" ? "HEALTH_OK" : report.overall === "unknown" ? "NOOP" : "HEALTH_WARN";
  const href = `/dashboard/servers/${server.id}?tab=mods`;
  if (action.kind === "restart") {
    const busy = await db.job.count({ where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } } });
    if (!busy) {
      await db.job.create({ data: { type: "GAME_POWER", serverId: server.id, payload: { action: "restart", announce: false, source: "auto-restart" } } });
      status = "HEALTH_RESTARTED";
    }
  } else if (action.kind === "pause") {
    const first = action.mods[0];
    const row = await db.serverMod.findFirst({ where: { serverId: server.id, status: "INSTALLED", mod: { sourceId: first.mod.key } }, select: { modId: true, mod: true } });
    // Only auto-pause where the vetting says a disable is clean: never a mod
    // whose disable could delete world content (that needs the owner's say-so).
    const d = row ? toggleDecision({ family, variant: server.gameVariant, mod: row.mod, engine: !!engineInstallerFor(family, row.mod.source) }) : null;
    if (row && d?.allowed && !d.needsAck) {
      const r = await enqueueModOp(server.id, row.modId, "disable", { userId: server.userId, slug: first.mod.key });
      if (r.ok) status = "HEALTH_PAUSED";
    }
  }
  // A pause that didn't happen (policy refused it, or the queue was busy) must not be reported as one.
  const summary = healthSummary(report, action.kind === "pause" && status !== "HEALTH_PAUSED" ? { kind: "notify", why: action.why } : action);
  await db.modUpdateRun.create({
    data: {
      serverId: server.id, trigger: "health", status, summary,
      plan: { startedAt: startedAt.toISOString(), verdicts: report.verdicts.map((v) => ({ name: v.mod.name, status: v.status, evidence: v.evidence })), action: action.kind } as never,
      finishedAt: new Date(),
    },
  });
  // Tell the customer only when something needs them (never "all good" noise).
  if (report.overall === "warn") {
    await db.notification
      .create({ data: { userId: server.userId, title: `${server.hostname}: a mod needs a look`, body: summary, href } })
      .catch(() => {});
  }
}

export type { Job };
/**
 * Enable/disable WITHOUT uninstalling — what each game really allows.
 *
 * This is the vetting (/root/agent-notes/mods-rework/VETTING.md, summarised in
 * docs/DOCUMENTATION.md) turned into code, so the portal, the server actions
 * and the worker all ask the same question and get the same answer. It is
 * PURE: no DB, no network, no guest.
 *
 * Three verdicts per family:
 *   SAFE              — taking the mod out of the load path and putting it back
 *                       loses nothing; the mod's own data/config stays on disk.
 *   SAFE_WITH_WARNING — the toggle itself is mechanically clean and reversible,
 *                       BUT a mod that adds content (blocks, items, buildings,
 *                       creatures, prototypes) is deleted from the world the
 *                       first time the game loads and saves without it.
 *                       Re-enabling does NOT bring that content back. Those
 *                       toggles need the owner to acknowledge it, and the panel
 *                       offers a world backup first.
 *   NOT_SUPPORTED     — either nobody has built a toggle for this family on
 *                       Nxeon (no state file to move files with), or it can't
 *                       be done honestly. The panel draws no toggle at all.
 *
 * A toggle is ONLY offered for families whose installs go through the shared
 * engine (lib/mods/engine.ts), because that is the only path that records
 * exactly which files Nxeon placed (/root/.nxeon-mods/state.json) — moving
 * files we can't name precisely is how a "disable" deletes the wrong thing.
 */

export type ToggleSafety = "SAFE" | "SAFE_WITH_WARNING" | "NOT_SUPPORTED";
/** move-aside: files move to /root/.nxeon-mods/disabled/<key>/…; native-flag: the game's own mod list says enabled=false. */
export type ToggleStrategy = "move-aside" | "native-flag" | "none";
/** hot: the framework unloads/loads on its own; restart: next game start. */
export type ToggleRestart = "hot" | "restart" | "none";

export type FamilyTogglePolicy = {
  family: string;
  safety: ToggleSafety;
  strategy: ToggleStrategy;
  restart: ToggleRestart;
  /** One plain sentence for the customer: how a disable works on this game. */
  how: string;
  /** Why NOT_SUPPORTED (customer-facing), or the general caveat otherwise. */
  note: string | null;
};

export type ToggleModFacts = {
  name: string;
  /** GameMod.category (Nxeon's coarse bucket). */
  category: string;
  /** GameMod.categories (provider categories, e.g. Modrinth "worldgen"). */
  categories?: string[] | null;
  tags?: string[] | null;
  loaders?: string[] | null;
};

export type ToggleDecision =
  | { allowed: false; safety: "NOT_SUPPORTED"; reason: string }
  | {
      allowed: true;
      safety: "SAFE" | "SAFE_WITH_WARNING";
      strategy: Exclude<ToggleStrategy, "none">;
      restart: ToggleRestart;
      /** This specific mod may delete world content when disabled. */
      contentRisk: boolean;
      /** Customer-facing warning shown before a disable (null = none needed). */
      warning: string | null;
      /** The server refuses the disable unless the owner acknowledged the warning. */
      needsAck: boolean;
    };

const PLUGIN_VARIANTS = new Set(["paper", "purpur", "spigot", "bukkit", "folia", "pufferfish", "leaf"]);
const MOD_VARIANTS = new Set(["fabric", "quilt", "forge", "neoforge"]);

/** Families with an engine installer — the only ones a toggle can exist for. Kept in step with lib/mods/installers/index.ts by a test. */
export const TOGGLE_ENGINE_FAMILIES = ["minecraft", "valheim", "rust", "cs2", "factorio", "corekeeper"] as const;

const NOT_BUILT = "Disabling without uninstalling isn't available for this game on Nxeon yet — remove the mod instead, and reinstall it from the store later.";

/** Customer-facing reason per non-engine family (from the vetting). */
const NOT_SUPPORTED_REASON: Record<string, string> = {
  terraria: NOT_BUILT,
  ark: "ARK downloads its mods itself from the mod list, and a mod taken off that list deletes its structures, dinos and items from the save. Remove it instead if you're sure.",
  projectzomboid: NOT_BUILT,
  dst: NOT_BUILT,
  unturned: NOT_BUILT,
  squad: NOT_BUILT,
  soulmask: NOT_BUILT,
  tf2: NOT_BUILT,
  l4d2: NOT_BUILT,
  kf2: NOT_BUILT,
  gmod: NOT_BUILT,
  necesse: NOT_BUILT,
  empyrion: "An Empyrion scenario is what your save is built on — it can't be switched off while the world uses it.",
  vintagestory: NOT_BUILT,
  satisfactory: NOT_BUILT,
  armareforger: NOT_BUILT,
};

export function familyTogglePolicy(family: string, variant: string | null): FamilyTogglePolicy {
  const v = (variant ?? "").toLowerCase();
  switch (family) {
    case "minecraft":
      if (PLUGIN_VARIANTS.has(v)) {
        return {
          family, safety: "SAFE", strategy: "move-aside", restart: "restart",
          how: "The plugin's jar is moved out of plugins/ and put back on enable; its config and data folder stay where they are.",
          note: "Plugins that others depend on can't be disabled while those are enabled.",
        };
      }
      return {
        family, safety: "SAFE_WITH_WARNING", strategy: "move-aside", restart: "restart",
        how: MOD_VARIANTS.has(v)
          ? "The mod's jar is moved out of mods/ and put back on enable; its config stays."
          : "The datapack is moved out of the world's datapacks/ folder and put back on enable.",
        note: "Mods that add blocks, items or creatures lose them from the world when the server starts without the mod.",
      };
    case "valheim":
      return {
        family, safety: "SAFE_WITH_WARNING", strategy: "move-aside", restart: "restart",
        how: "The plugin folder is moved out of BepInEx's plugins and put back on enable; its config stays.",
        note: "Mods that add items, building pieces or creatures lose them from the world. Players whose game also runs the mod may need to match the server.",
      };
    case "rust":
      return {
        family, safety: "SAFE", strategy: "move-aside", restart: "hot",
        how: "The plugin's .cs file is moved out of the plugins folder — the framework unloads it on its own. Its config and data files stay.",
        note: null,
      };
    case "cs2":
      return {
        family, safety: "SAFE", strategy: "move-aside", restart: "restart",
        how: "The plugin folder is moved out of CounterStrikeSharp's plugins and put back on enable; its config stays.",
        note: null,
      };
    case "factorio":
      return {
        family, safety: "SAFE_WITH_WARNING", strategy: "native-flag", restart: "restart",
        how: "The mod stays on disk and is switched off in Factorio's own mod-list.json.",
        note: "Factorio removes everything a disabled mod added (buildings, items, recipes) from the save when it loads.",
      };
    case "corekeeper":
      return {
        family, safety: "SAFE_WITH_WARNING", strategy: "move-aside", restart: "restart",
        how: "The mod folder is moved out of the Mods folder and put back on enable.",
        note: "Mods that add items or blocks lose them from the world when the server starts without them.",
      };
    default:
      return {
        family, safety: "NOT_SUPPORTED", strategy: "none", restart: "none",
        how: "",
        note: NOT_SUPPORTED_REASON[family] ?? "This game has no Nxeon-installed mods that can be switched off — remove them instead.",
      };
  }
}

/* ── content-risk heuristics ─────────────────────────────────────────────── */

const lc = (xs: (string | null | undefined)[] | null | undefined) => (xs ?? []).filter(Boolean).map((x) => String(x).toLowerCase());

/** Provider categories that mean "adds things to the world" (Modrinth / Thunderstore / mod.io wording). */
const CONTENT_CATS = new Set([
  "adventure", "equipment", "technology", "mobs", "decoration", "magic", "worldgen", "food", "storage",
  "transportation", "kitchen-sink", "content", "building", "item", "items", "world", "npc", "overhaul",
  "creatures", "weapons", "armor", "biomes", "structures", "dimensions",
]);
/** Categories that clearly don't (server-side behaviour, performance, libraries). */
const SAFE_CATS = new Set([
  "optimization", "library", "libraries", "utility", "management", "social", "lightweight", "admin", "admin_tools",
  "quality of life", "qol", "tweaks", "visual", "language", "performance", "chat", "dev_tools", "core",
]);

/**
 * Could disabling this specific mod delete things from the world? Errs toward
 * YES: a mod we can't classify on a content-capable game is treated as content.
 */
export function contentRisk(family: string, variant: string | null, mod: ToggleModFacts): { risk: boolean; why: string } {
  const pol = familyTogglePolicy(family, variant);
  if (pol.safety !== "SAFE_WITH_WARNING") return { risk: false, why: "plugins on this game don't add world content" };
  const cats = new Set([...lc([mod.category]), ...lc(mod.categories), ...lc(mod.tags)]);
  const hit = [...cats].find((c) => CONTENT_CATS.has(c));
  if (hit) return { risk: true, why: `listed as "${hit}"` };
  if (family === "factorio") return { risk: true, why: "Factorio mods usually define prototypes the save stores" };
  if (family === "minecraft" && (cats.has("datapacks") || lc(mod.loaders).includes("datapack"))) {
    return { risk: true, why: "datapacks can add world generation, structures and dimensions" };
  }
  const known = [...cats].filter((c) => !["mods", "plugins", "misc", "other", "fun", "game-mechanics", "gameplay", "mechanics"].includes(c));
  if (known.length && known.every((c) => SAFE_CATS.has(c))) return { risk: false, why: `listed only as ${known.join(", ")}` };
  return { risk: true, why: "we can't tell from its listing whether it adds content" };
}

/** Modpacks are a bundle of other packages + config overrides: "disable" isn't meaningful. */
export function isModpack(mod: ToggleModFacts): boolean {
  const cats = new Set([...lc([mod.category]), ...lc(mod.categories)]);
  return cats.has("modpacks") || cats.has("modpack") || lc(mod.loaders).includes("mrpack");
}

/** May THIS installed mod be enabled/disabled on THIS server, and with what warning? */
export function toggleDecision(input: {
  family: string;
  variant: string | null;
  mod: ToggleModFacts;
  /** The mod was installed by the engine (an installer handles its source). */
  engine: boolean;
}): ToggleDecision {
  const pol = familyTogglePolicy(input.family, input.variant);
  if (pol.safety === "NOT_SUPPORTED" || pol.strategy === "none") return { allowed: false, safety: "NOT_SUPPORTED", reason: pol.note ?? NOT_BUILT };
  if (!input.engine) return { allowed: false, safety: "NOT_SUPPORTED", reason: NOT_BUILT };
  if (isModpack(input.mod)) {
    return { allowed: false, safety: "NOT_SUPPORTED", reason: "A modpack is a bundle of mods and settings — it can't be switched off as one. Remove it, or disable individual mods instead." };
  }
  const cr = contentRisk(input.family, input.variant, input.mod);
  const warning = cr.risk
    ? `${input.mod.name} may add things to your world (${cr.why}). While it's disabled, the game deletes them the first time those areas load and save — turning it back on does NOT bring them back. Back up the world first.`
    : pol.safety === "SAFE_WITH_WARNING" && pol.note
      ? pol.note
      : null;
  return {
    allowed: true,
    safety: cr.risk ? "SAFE_WITH_WARNING" : "SAFE",
    strategy: pol.strategy,
    restart: pol.restart,
    contentRisk: cr.risk,
    warning,
    needsAck: cr.risk,
  };
}

/* ── dependency awareness (pure; graph comes from the guest state) ──────── */

/** modId → the other installed root modIds it needs (direct or through shared packages). */
export type DepGraph = Record<string, string[]>;

export type PlannedToggle = { modId: string; op: "disable" | "enable" };

/**
 * Check a batch of toggles against the dependency graph and the current
 * enabled set. Returns the problems (customer-facing) and a safe ORDER to
 * apply them in: disables of dependents before the things they need, enables
 * of needed things before their dependents.
 */
export function planToggles(
  plan: PlannedToggle[],
  graph: DepGraph,
  enabled: Set<string>,
  names: Record<string, string>,
): { ok: boolean; problems: string[]; order: PlannedToggle[] } {
  const after = new Set(enabled);
  for (const p of plan) (p.op === "disable" ? after.delete(p.modId) : after.add(p.modId));
  const nm = (id: string) => names[id] ?? "another mod";
  const problems: string[] = [];
  for (const p of plan) {
    if (p.op === "disable") {
      const needers = Object.entries(graph).filter(([id, req]) => id !== p.modId && after.has(id) && req.includes(p.modId)).map(([id]) => nm(id));
      if (needers.length) problems.push(`${needers.join(", ")} need${needers.length === 1 ? "s" : ""} ${nm(p.modId)} — disable ${needers.length === 1 ? "it" : "them"} too, or keep ${nm(p.modId)} on.`);
    } else {
      const missing = (graph[p.modId] ?? []).filter((d) => d !== p.modId && !after.has(d) && d in names).map(nm);
      if (missing.length) problems.push(`${nm(p.modId)} needs ${missing.join(", ")} — enable ${missing.length === 1 ? "it" : "them"} too.`);
    }
  }
  // Order: all disables first (dependents before dependencies), then enables (dependencies first).
  const depth = (id: string, seen = new Set<string>()): number => {
    if (seen.has(id)) return 0;
    seen.add(id);
    const req = graph[id] ?? [];
    return req.length ? 1 + Math.max(...req.map((r) => depth(r, seen))) : 0;
  };
  const dis = plan.filter((p) => p.op === "disable").sort((a, b) => depth(b.modId) - depth(a.modId));
  const en = plan.filter((p) => p.op === "enable").sort((a, b) => depth(a.modId) - depth(b.modId));
  return { ok: problems.length === 0, problems, order: [...dis, ...en] };
}
/**
 * Cyrus mods through the shared mods engine (source "cyrus").
 *
 * A Cyrus mod is a Paper plugin jar built by Cyrus (ModBuild, jar stored on the
 * primary under /var/lib/nxeon/modbuilds). Routing its installs through
 * lib/mods/engine.ts — instead of the old direct copy — means the guest state
 * file records exactly which jar Nxeon placed, so the Mods tab can list it,
 * switch it off/on, update it, roll it back and uninstall it like any
 * catalogue plugin (backups, staged write, rollback included).
 *
 * GameMod row: gameFamily "minecraft", source "cyrus", sourceId = the chain's
 * rootBuildId, active=false (never listed in the catalogue/store), created by
 * lib/cyrus-mods/registry.ts. The version placed is CatalogFacts.targetVersionId
 * (a ModBuild id, for update/rollback), else the chain's current version.
 *
 * The jar never leaves the primary over the network: it is read from disk and
 * handed to the engine as a prefetched package (sha256 checked against the
 * stored ModBuild.jarSha256).
 */
import { createHash } from "node:crypto";
import type { CatalogFacts, InstallerCtx, Resolution } from "../types";

export const CYRUS_SOURCE = "cyrus";
/** Generated plugins target the Paper API (Adventure etc.); Spigot/Bukkit can't load them, Folia isn't safe. */
export const CYRUS_VARIANTS = ["paper", "purpur"];

export type CyrusJar = {
  build: { id: string; version: string | null; pluginName: string | null; jarName: string; jarSha256: string | null; mcVersion: string };
  /** Display name of the mod (page title). */
  name: string;
  /** Unique package version within the chain (version string, disambiguated when two versions share one). */
  packageVersion: string;
  bytes: Buffer;
};

/** Where jars come from. Default: the DB + jar store (./../../cyrus-mods/registry). Tests swap it. */
export type CyrusJarSource = (args: { rootBuildId: string; targetBuildId: string | null; serverId: string }) => Promise<CyrusJar | { error: string }>;

let source: CyrusJarSource | null = null;
export function setCyrusJarSource(fn: CyrusJarSource | null) {
  source = fn;
}
async function jarSource(): Promise<CyrusJarSource> {
  if (source) return source;
  const m = await import("../../cyrus-mods/registry");
  return m.loadCyrusJar;
}

export const cyrusPackageKey = (rootBuildId: string) => `cyrus:${rootBuildId}`;

export async function resolveCyrus(mod: CatalogFacts, ctx: InstallerCtx): Promise<Resolution | { error: string }> {
  const variant = (ctx.server.variant ?? "vanilla").toLowerCase();
  if (!CYRUS_VARIANTS.includes(variant)) return { error: `Cyrus mods are Paper plugins — this server runs ${variant}. Switch it to Paper or Purpur in Settings first.` };
  if (!mod.sourceId) return { error: "This Cyrus mod has no build history to install from." };
  const got = await (await jarSource())({ rootBuildId: mod.sourceId, targetBuildId: mod.targetVersionId ?? null, serverId: ctx.server.id });
  if ("error" in got) return got;
  const sha = createHash("sha256").update(got.bytes).digest("hex");
  if (got.build.jarSha256 && got.build.jarSha256 !== sha) return { error: "The stored plugin file doesn't match its checksum — nothing was installed. Rebuild it in Cyrus." };
  const notes: string[] = [];
  if (ctx.layout.gameVersion && got.build.mcVersion && ctx.layout.gameVersion !== got.build.mcVersion) {
    notes.push(`Built for Minecraft ${got.build.mcVersion}; your server runs ${ctx.layout.gameVersion}. Paper plugins usually carry across 1.21.x — check the console after the restart.`);
  }
  return {
    packages: [
      {
        key: cyrusPackageKey(mod.sourceId),
        name: got.name,
        version: got.packageVersion,
        versionId: got.build.id,
        file: { url: `cyrus://${got.build.id}`, filename: got.build.jarName, size: got.bytes.length, hashes: { sha256: sha } },
        placement: "plugin-jar",
        requires: [],
        incompatible: [],
        prefetched: got.bytes,
        root: true,
      },
    ],
    notes,
  };
}

