"use client";

import { useCallback, useEffect, useRef, useState, useTransition, useMemo } from "react";
import { Icon } from "@/components/nx/Icon";
import {
  checkModUpdates,
  getModsOverview,
  panelApplyModBatch,
  panelInstallMod,
  panelRemoveMod,
  panelUpdateMod,
  previewModInstall,
  type InstallPreview,
  type InstalledMod,
  type ModsOverview,
} from "@/lib/actions-mod-installs";
import { createGameBackup, gamePower } from "@/lib/actions-game-control";
import type { ModLoad } from "@/lib/mod-load";
import type { Compat } from "@/lib/mods/types";
import type { BrowseCard } from "@/lib/mods-browse";
import { ModBrowser } from "@/components/customer/mods/browser/ModBrowser";
import { AutoUpdatePanel } from "@/components/customer/mods/AutoUpdatePanel";
import { Chip, InstalledLibrary, ModIcon, PENDING, SOURCE_LABEL, fileSize, hasUpdateFor, type StagedOp } from "./mods/InstalledLibrary";
import { HealthView, healthIssues } from "./mods/HealthView";
import { CyrusVersionsDialog, CyrusUpdates } from "./mods/CyrusVersions";

/**
 * Mods & Plugins — ONE primary view and three secondary ones (2026-10-07
 * declutter; every capability of the earlier stacked layout is kept):
 *
 *  INSTALLED (default when anything is installed): the server's library —
 *    version, source, health, updates, dependencies, uninstall, staged on/off
 *    switches where the vetting (lib/mods/toggle-policy.ts) allows them, and
 *    Cyrus mods (badge + version history / update / rollback).
 *  BROWSE: the whole catalogue for this game with compatibility for THIS
 *    server and a live dependency preview before install. (The old Mods /
 *    Plugins sub-tabs became the store's category filter.)
 *  UPDATES: one-off updates, automatic updates, schedule, player profiles,
 *    history (components/customer/mods/AutoUpdatePanel.tsx).
 *  HEALTH: load on this tier, per-mod load verdicts from the game log,
 *    failed installs, dependencies, manual installs + backups.
 *
 * Above the views there is at most one compact notice per live condition
 * (job progress, restart needed, one-click paused, heavy load) instead of
 * stacked banner cards. Deep links: ?tab=mods#mod-updates / #mod-health /
 * #mod-store, ?tab=plugins opens Browse on plugins.
 *
 * Honesty rules (unchanged): every number is the source's own or absent; a
 * change the worker could not apply comes back as a failure with its reason;
 * when one-click changes are switched off the tab says so and offers no
 * button that would only fail.
 */

const PLUGIN_CATS = ["admin", "permission", "protection", "economy", "chat", "discord", "core", "utility", "clan", "rank", "teleport", "plugins"];

/** What the install dialog needs — satisfied by a browser card. */
type InstallTarget = { id: string; name: string; source: string; iconUrl: string | null; compat: Compat | null; impact: string; impactNote: string | null; url: string | null };
const fromCard = (m: BrowseCard): InstallTarget => ({ id: m.id, name: m.name, source: m.source, iconUrl: m.icon, compat: m.compat, impact: m.impact, impactNote: null, url: null });

export type ModsView = "installed" | "browse" | "updates" | "health";
const HASH: Record<string, ModsView> = { "#mod-updates": "updates", "#mod-health": "health", "#mod-store": "browse", "#mod-installed": "installed" };
const HASH_OF: Record<ModsView, string> = { installed: "#mod-installed", browse: "#mod-store", updates: "#mod-updates", health: "#mod-health" };

function Notice({ tone, icon, title, body, action, live }: { tone: "info" | "warn" | "bad" | "ok"; icon: string; title: React.ReactNode; body?: React.ReactNode; action?: React.ReactNode; live?: boolean }) {
  const t = {
    info: "border-cyan/35 bg-cyan/[0.07] text-cyan",
    warn: "border-amber/45 bg-amber/[0.08] text-amber",
    bad: "border-rose/40 bg-rose/[0.08] text-rose",
    ok: "border-mint/35 bg-mint/[0.08] text-mint",
  }[tone];
  return (
    <div className={"flex flex-wrap items-center gap-x-3 gap-y-2 rounded-[13px] border px-3.5 py-2.5 " + t} role={tone === "bad" ? "alert" : "status"} aria-live={live ? "polite" : undefined}>
      <Icon name={icon} size={14} tone="inherit" className={"flex-none " + (icon === "refresh" ? "animate-spin" : "")} />
      <div className="min-w-0 flex-1">
        <p className="text-[12.5px] font-bold">{title}</p>
        {body && <div className="mt-0.5 text-[12px] leading-relaxed text-tx-dim">{body}</div>}
      </div>
      {action}
    </div>
  );
}

export function ModsPanel({ serverId, scope }: { serverId: string; scope: "mods" | "plugins" }) {
  const [ov, setOv] = useState<ModsOverview | null>(null);
  const [fatal, setFatal] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [view, setViewState] = useState<ModsView | null>(null);
  const [total, setTotal] = useState<number | null>(null);
  const [refreshKey, setRefreshKey] = useState(0);
  const [confirm, setConfirm] = useState<InstallTarget | null>(null);
  const [removing, setRemoving] = useState<InstalledMod | null>(null);
  const [versionsOf, setVersionsOf] = useState<InstalledMod | null>(null);
  const [riskBatch, setRiskBatch] = useState<{ changes: { modId: string; op: StagedOp }[]; risky: InstalledMod[] } | null>(null);
  const [updates, setUpdates] = useState<Record<string, string | null> | null>(null);
  const [checking, setChecking] = useState(false);
  const [restarting, setRestarting] = useState(false);
  const [, start] = useTransition();

  const setView = useCallback((v: ModsView) => {
    setViewState(v);
    try {
      const url = new URL(window.location.href);
      url.hash = HASH_OF[v];
      window.history.replaceState(window.history.state, "", url);
    } catch { /* non-browser */ }
  }, []);

  const loadOverview = useCallback(async () => {
    const r = await getModsOverview(serverId).catch(() => ({ error: "Couldn't load your mods." }) as { error: string });
    if ("view" in r && r.view) {
      setOv(r.view);
      setFatal(null);
    } else if ("error" in r && r.error) setFatal(r.error);
  }, [serverId]);

  useEffect(() => { void loadOverview(); }, [loadOverview]);

  // First view: a deep link (#mod-updates…) or ?tab=plugins wins; else the
  // library when there is one, the store when there isn't.
  useEffect(() => {
    if (!ov || view !== null) return;
    const fromHash = typeof window !== "undefined" ? HASH[window.location.hash] : undefined;
    setViewState(fromHash ?? (scope === "plugins" ? "browse" : ov.installed.some((m) => m.status !== "REMOVED") ? "installed" : "browse"));
  }, [ov, view, scope]);

  // Plugins deep link = the catalogue's admin-ish categories (a filter, said plainly).
  const pluginCategory = useMemo(() => {
    if (scope !== "plugins" || !ov) return null;
    return ov.categories.find((c) => PLUGIN_CATS.some((k) => c.category.toLowerCase().includes(k)))?.category ?? null;
  }, [scope, ov]);

  // Follow the job while one is queued/running, then refresh the store's results once.
  const active = !!ov?.job || (ov?.installed ?? []).some((m) => m.status && PENDING.has(m.status));
  const wasActive = useRef(false);
  useEffect(() => {
    if (!active) {
      if (wasActive.current) {
        wasActive.current = false;
        setRefreshKey((k) => k + 1);
      }
      return;
    }
    wasActive.current = true;
    const t = setInterval(() => void loadOverview(), 3000);
    return () => clearInterval(t);
  }, [active, loadOverview]);

  const run = (fn: () => Promise<{ error?: string } | null | undefined>, ok?: string) =>
    start(async () => {
      setError(null);
      setNotice(null);
      const r = await fn().catch(() => ({ error: "Couldn't reach the server." }));
      if (r && r.error) setError(r.error);
      else if (ok) setNotice(ok);
      await loadOverview();
      setRefreshKey((k) => k + 1);
    });

  const install = (m: InstallTarget, ackClient: boolean) => {
    setConfirm(null);
    run(() => panelInstallMod(serverId, m.id, { ackClient }), `Installing ${m.name} — it will appear under Installed.`);
  };
  const applyBatch = (changes: { modId: string; op: StagedOp }[], ackRisk: boolean) => {
    setRiskBatch(null);
    run(() => panelApplyModBatch(serverId, changes, { ackRisk }));
  };

  const restartNow = () =>
    start(async () => {
      setRestarting(true);
      setError(null);
      const r = await gamePower(serverId, "restart").catch(() => ({ ok: false as const, error: "Couldn't reach the server." }));
      if (!r.ok) setError(r.error);
      await loadOverview();
      setRestarting(false);
    });

  const doCheckUpdates = () =>
    start(async () => {
      setChecking(true);
      const r = await checkModUpdates(serverId).catch(() => ({ error: "Couldn't check for updates." }) as { error: string });
      if ("updates" in r && r.updates) setUpdates(r.updates);
      else if ("error" in r && r.error) setError(r.error);
      setChecking(false);
    });

  if (!ov && !fatal) {
    return <div className="rounded-[16px] border border-rim-hi bg-surface px-6 py-16 text-center text-[13px] text-tx-dim">Loading mods…</div>;
  }
  if (!ov) {
    return (
      <div className="rounded-[16px] border border-rim-hi bg-surface px-6 py-14 text-center">
        <Icon name="cube" size={28} className="mx-auto" />
        <p className="mt-3 text-[14.5px] font-bold text-tx">Mods aren&apos;t available for this game</p>
        <p className="mx-auto mt-1.5 max-w-[52ch] text-[12.5px] leading-relaxed text-tx-dim">{fatal}</p>
      </div>
