  error: string | null;
};

/** One row of the Installed library: the catalogue facts plus what's true on THIS server. */
export type InstalledMod = PanelMod & {
  installedAt: string | null;
  /** Newer compatible version the auto-update checker found (null = none / never checked). */
  availableVersion: string | null;
  pinned: boolean;
  /** Last mod-health verdict after a game start, when the game's log can be read per mod. */
  health: { status: "loaded" | "error" | "not-seen" | "unknown"; evidence: string | null; checkedAt: string } | null;
  /** Enable/disable verdict from the vetting (lib/mods/toggle-policy.ts). */
  toggle: ToggleDecision;
  /** Other installed mods this one needs / that need this one (from the server's own mod state). */
  dependsOn: string[];
  neededBy: string[];
  dependsOnIds: string[];
  neededByIds: string[];
  /** Set for mods built with Cyrus (source "cyrus"): installed vs latest version, history size, page. */
  cyrus: CyrusRowInfo | null;
};

export type ModsOverview = {
  family: string;
  familyName: string;
  variant: string | null;
  gameVersion: string | null;
  coverage: { mode: "engine" | "legacy" | "unavailable"; text: string; canUpdate: boolean; canToggle: boolean };
  /** False when the worker would refuse every change (ENABLE_REAL_GAMEMODS off in production). */
  installsLive: boolean;
  togglePolicy: FamilyTogglePolicy;
  installed: InstalledMod[];
  /** Dependency graph as of the last mod job (null = not known yet). */
  depsKnownAt: string | null;
  lastWorldBackupAt: string | null;
  backupRunning: boolean;
  categories: { category: string; count: number }[];
  catalogTotal: number;
  job: { id: string; status: string; step: string | null; progress: number } | null;
  restart: { required: boolean; changed: string[]; since: string | null };
  load: ModLoad;
  serverRunning: boolean;
  /** Cyrus builds an older (pre-engine) install put on this server that aren't tracked yet. */
  untrackedCyrus: UntrackedCyrus[];
};

type ModRow = GameMod;

function compatFor(family: string, m: ModRow, facts: ReturnType<typeof serverFacts>): Compat {
  const inst = engineInstallerFor(family, m.source) ?? ENGINE_INSTALLERS[family];
  if (inst) return inst.compat(catalogFacts(m), facts);
  const c = modCompat({ gameVersions: m.gameVersions, loaders: m.loaders, serverSide: m.serverSide }, { gameVersion: facts.pinnedVersion, variant: facts.variant });
  return c.verdict === "unknown" ? { verdict: "unknown", detail: c.detail, reason: c.reason } : (c as Compat);
}

function toPanel(family: string, m: ModRow, facts: ReturnType<typeof serverFacts>, st?: { status: string; version: string | null; error: string | null } | null): PanelMod {
  const sup = installSupport(family, m.source);
  const cov = familyCoverage(family);
  const compat = compatFor(family, m, facts);
  return {
    id: m.id,
    name: m.name,
    slug: m.slug,
    category: m.category,
    source: m.source,
    url: m.url,
    description: m.description,
    iconUrl: m.iconUrl,
    authorName: m.authorName,
    downloads: m.downloads,
    fileBytes: m.fileBytes,
    dependencyCount: m.dependencyCount,
    impact: m.impact,
    impactNote: m.impactNote,
    paid: m.paid,
    featured: m.featured,
    gameVersions: m.gameVersions.slice(-8),
    loaders: m.loaders.slice(0, 6),
    latestUpdated: m.upstreamUpdatedAt ? m.upstreamUpdatedAt.toISOString() : null,
    compat,
    manualInstall: cov.mode === "unavailable" ? cov.reason : !sup.ok ? sup.message : compat.verdict === "unsupported" ? compat.detail : null,
    status: st?.status ?? null,
    version: st?.version ?? null,
    error: st?.error ?? null,
  };
}

/** Everything the panel needs except the catalogue page itself. */
export async function getModsOverview(serverId: string): Promise<{ error?: string; view?: ModsOverview }> {
  const { server, family } = await ownedServer(serverId);
  if (!family) return { error: "This server doesn't support mods." };
  const facts = serverFacts(server, family);
  const cov = familyCoverage(family);

  const [rows, cats, total, job, lastSync, lastPower, lastGraph, lastBackup, health] = await Promise.all([
    db.serverMod.findMany({ where: { serverId }, include: { mod: true }, orderBy: { installedAt: "asc" } }),
    db.gameMod.groupBy({ by: ["category"], where: { gameFamily: family, active: true, upstreamOk: true, duplicateOfId: null }, _count: { _all: true } }),
    db.gameMod.count({ where: { gameFamily: family, active: true, upstreamOk: true, duplicateOfId: null } }),
    db.job.findFirst({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } }, orderBy: { createdAt: "desc" }, select: { id: true, type: true, status: true, step: true, progress: true } }),
    db.job.findFirst({ where: { serverId, type: "GAME_MOD_SYNC", status: "DONE" }, orderBy: { updatedAt: "desc" }, select: { updatedAt: true, payload: true } }),
    db.job.findFirst({ where: { serverId, type: { in: ["GAME_POWER", "GAME_REINSTALL"] }, status: "DONE" }, orderBy: { updatedAt: "desc" }, select: { updatedAt: true, payload: true } }),
    lastDepGraph(serverId),
    db.job.findFirst({ where: { serverId, type: "GAME_BACKUP", status: "DONE" }, orderBy: { updatedAt: "desc" }, select: { updatedAt: true } }),
    db.modUpdateRun.findFirst({ where: { serverId, trigger: "health" }, orderBy: { startedAt: "desc" }, select: { startedAt: true, plan: true } }).catch(() => null),
  ]);

  const result = (lastSync?.payload as { result?: { restartRequired?: boolean; changed?: string[] } } | null)?.result;
  const powerAction = (lastPower?.payload as { action?: string } | null)?.action;
  const restartedSince = !!lastPower && !!lastSync && lastPower.updatedAt > lastSync.updatedAt && powerAction !== "stop";
  const restart = {
    required: !!result?.restartRequired && !restartedSince,
    changed: result?.changed ?? [],
    since: lastSync?.updatedAt.toISOString() ?? null,
  };

  const graph = lastGraph?.graph ?? null;
  const [cyrus, untrackedCyrus] = await Promise.all([
    cyrusInfoForRows(rows).catch(() => new Map<string, CyrusRowInfo>()),
    family === "minecraft" ? untrackedCyrusInstalls(serverId, server.userId).catch(() => []) : Promise.resolve([] as UntrackedCyrus[]),
  ]);
  const verdicts = ((health?.plan as { verdicts?: { name: string; status: string; evidence: string | null }[] } | null)?.verdicts ?? []);
  const nameOf = new Map(rows.map((r) => [r.modId, r.mod.name]));
  const installed: InstalledMod[] = rows
    .filter((r) => r.mod.gameFamily === family)
    .map((r) => {
      const v = verdicts.find((x) => x.name === r.mod.name);
      const cy = cyrus.get(r.modId) ?? null;
      return {
        ...toPanel(family, r.mod, facts, r),
        installedAt: r.installedAt.toISOString(),
        // Cyrus mods: "newer version" comes from the build chain, not the auto-update checker.
        availableVersion: cy ? (cy.updateAvailable ? cy.latestPackageVersion : null) : r.availableVersion ?? null,
        cyrus: cy,
        pinned: r.pinned,
        health: v && health ? { status: v.status as "loaded" | "error" | "not-seen" | "unknown", evidence: v.evidence ?? null, checkedAt: health.startedAt.toISOString() } : null,
        toggle: toggleDecision({ family, variant: server.gameVariant ?? null, mod: r.mod, engine: !!engineInstallerFor(family, r.mod.source) }),
        dependsOnIds: (graph?.[r.modId] ?? []).filter((id) => nameOf.has(id)),
        neededByIds: graph ? Object.entries(graph).filter(([id, req]) => id !== r.modId && req.includes(r.modId) && nameOf.has(id)).map(([id]) => id) : [],
        dependsOn: (graph?.[r.modId] ?? []).map((id) => nameOf.get(id)).filter((n): n is string => !!n),
        neededBy: graph ? Object.entries(graph).filter(([id, req]) => id !== r.modId && req.includes(r.modId)).map(([id]) => nameOf.get(id)).filter((n): n is string => !!n) : [],
      };
    });
  const live = rows.filter((r) => ["INSTALLED", "INSTALLING", "UPDATING", "ENABLING"].includes(r.status));
  const pol = familyTogglePolicy(family, server.gameVariant ?? null);
  return {
    view: {
      family,
      familyName: GAME_DISPLAY[family as GameFamily]?.name ?? family,
      variant: server.gameVariant ?? null,
      gameVersion: facts.pinnedVersion,
      coverage: {
        mode: cov.mode,
        text: customerCoverageText(family),
        canUpdate: cov.mode === "engine",
        canToggle: cov.mode === "engine" && pol.safety !== "NOT_SUPPORTED",
      },
      installsLive: installsLive(),
      togglePolicy: pol,
      installed,
      depsKnownAt: lastGraph?.updatedAt.toISOString() ?? null,
      lastWorldBackupAt: lastBackup?.updatedAt.toISOString() ?? null,
      backupRunning: job?.type === "GAME_BACKUP",
      categories: cats.map((c) => ({ category: c.category, count: c._count._all })).sort((a, b) => b.count - a.count),
      catalogTotal: total,
      job: job
        ? { id: job.id, status: job.status, step: job.type === "GAME_MOD_SYNC" ? job.step : "Another operation is running on this server", progress: job.progress }
        : null,
      restart,
      load: modLoad({
        ramMB: server.gamePlan?.ramMB ?? 0,
        installed: live.map((r) => ({ name: r.mod.name, fileBytes: r.mod.fileBytes, impact: r.mod.impact })),
      }),
      serverRunning: server.status === "RUNNING",
      untrackedCyrus,
    },
  };
}

