"use client";

// Install a built Cyrus plugin on one of the account's Paper/Purpur servers (POST
// /api/mod-builder/builds/:id/install). Kept from the v4 studio unchanged; portalled to <body>
// with the token modal's look (.cy-tokens / .cy-modal in app/dashboard/cyrus/cyrus.css).
import Link from "next/link";
import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import type { ModBuildView } from "@/lib/modbuilder/types";
import type { MbServer } from "@/lib/modbuilder/install";
import { CyIcon, NeonDefs } from "./icons";

export function Modal({ title, sub, onClose, children, wide }: { title: string; sub?: string; onClose: () => void; children: React.ReactNode; wide?: boolean }) {
  useEffect(() => {
    const k = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", k);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => { window.removeEventListener("keydown", k); document.body.style.overflow = prev; };
  }, [onClose]);
  // Portalled to <body> so it sits above the portal's own top bar; .cy-tokens carries the theme.
  const [host, setHost] = useState<HTMLElement | null>(null);
  useEffect(() => setHost(document.body), []);
  if (!host) return null;
  return createPortal(
    <div className="cy-tokens cy-modal-back" role="dialog" aria-modal="true" aria-label={title} onMouseDown={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <NeonDefs />
      <div className={`cy-modal ${wide ? "wide" : ""}`}>
        <div className="cy-modal-h">
          <div className="flex min-w-0 flex-col gap-1">
            <h2>{title}</h2>
            {sub && <p>{sub}</p>}
          </div>
          <button type="button" className="cy-ib ml-auto" onClick={onClose} aria-label="Close"><CyIcon name="x" size={14} /></button>
        </div>
        {children}
      </div>
    </div>,
    host,
  );
}

export function InstallModal({ build, servers, onClose, onDone }: { build: ModBuildView; servers: MbServer[]; onClose: () => void; onDone: () => void }) {
  const firstOk = servers.find((s) => s.compatible);
  const [sel, setSel] = useState<string | null>(build.lastInstall?.serverId && servers.some((s) => s.id === build.lastInstall!.serverId && s.compatible) ? build.lastInstall.serverId : firstOk?.id ?? null);
  const chosen = servers.find((s) => s.id === sel);
  const [restart, setRestart] = useState(true);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [done, setDone] = useState<null | { replaced: string[]; restarted: boolean; restartNote: string | null }>(null);

  async function go() {
    if (!sel) return;
    setBusy(true); setErr(null);
    try {
      const r = await fetch(`/api/mod-builder/builds/${build.id}/install`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ serverId: sel, restart: restart && chosen?.status === "RUNNING" }) });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) { setErr(j.error || "The install didn't go through."); setBusy(false); return; }
      setDone(j); setBusy(false); onDone();
    } catch { setErr("We couldn't reach Nxeon. Try again."); setBusy(false); }
  }

  if (done) {
    return (
      <Modal title="Installed" onClose={onClose}>
        <div className="cy-done">
          <span className="cy-done-orb"><CyIcon name="check" size={22} strokeWidth={2.4} /></span>
          <p className="cy-done-t">{build.jarName} is on {chosen?.name}.</p>
          <p className="cy-sub max-w-[46ch] text-center">
            {done.restarted ? "The server is restarting now. Your mod loads as soon as it's back up (usually under a minute)."
              : done.restartNote ? `We couldn't restart it automatically: ${done.restartNote} Restart it from the server page to load the mod.`
              : "Restart the server to load the mod. Paper doesn't load new plugins while it's running."}
            {done.replaced.length > 0 && ` We replaced ${done.replaced.join(", ")} and kept a backup of it.`}
          </p>
          <div className="flex flex-wrap justify-center gap-2">
            <Link href={`/dashboard/servers/${sel}`} className="cy-btn primary">Open server <CyIcon name="chevr" size={13} /></Link>
            <button type="button" className="cy-btn" onClick={onClose}>Done</button>
          </div>
        </div>
      </Modal>
    );
  }

  return (
    <Modal title="Install to my server" sub={`Copies ${build.jarName} into the server's plugins folder.`} onClose={onClose}>
      {servers.length === 0 ? (
        <div className="cy-done">
          <span className="cy-done-orb dim"><CyIcon name="server" size={20} /></span>
          <p className="cy-done-t">You don&apos;t have a Minecraft server yet</p>
          <p className="cy-sub max-w-[40ch] text-center">Download the .jar and put it in any Paper server&apos;s plugins folder, or start a Paper server on Nxeon.</p>
          <Link href="/dashboard/deploy" className="cy-btn primary">Get a Minecraft server</Link>
        </div>
      ) : (
        <>
          <div className="cy-srvs" role="radiogroup" aria-label="Server">
            {servers.map((s) => (
              <label key={s.id} className={`cy-srv ${sel === s.id ? "on" : ""} ${s.compatible ? "" : "off"}`}>
                <input type="radio" name="cy-srv" className="sr-only" disabled={!s.compatible} checked={sel === s.id} onChange={() => setSel(s.id)} />
                <span className={`cy-srv-dot ${s.status === "RUNNING" ? "up" : ""}`} />
                <span className="flex min-w-0 flex-1 flex-col">
                  <b className="truncate">{s.name}</b>
                  <span className="cy-sub">{s.compatible ? `${cap(s.variant)} · ${s.status === "RUNNING" ? "online" : "stopped"}` : s.reason}</span>
                </span>
                {sel === s.id && <CyIcon name="check" size={15} />}
              </label>
            ))}
          </div>
          {chosen?.status === "RUNNING" && (
            <label className="cy-checkrow">
              <input type="checkbox" checked={restart} onChange={(e) => setRestart(e.target.checked)} />
              <span><b>Restart the server now</b> so the mod loads. Players get a short warning first.</span>
            </label>
          )}
          <p className="cy-sub">If an older version of {build.pluginName} is already there, we back it up before replacing it.</p>
          {err && <p role="alert" className="cy-err">{err}</p>}
          <div className="flex justify-end gap-2">
            <button type="button" className="cy-btn" onClick={onClose}>Cancel</button>
            <button type="button" className="cy-btn primary" disabled={!sel || busy} onClick={go}>
              {busy ? <i className="cy-spin" /> : <CyIcon name="server" size={14} />} {busy ? "Installing…" : "Install"}
            </button>
          </div>
        </>
      )}
    </Modal>
  );
}

const cap = (s: string | null) => (s ? s[0].toUpperCase() + s.slice(1) : "");
import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { installBuildToServer } from "@/lib/modbuilder/install";
import { gamePower } from "@/lib/actions-game-control";
import { checkRateLimit } from "@/lib/rate-limit";
import { NOT_FOUND, ownedBuild } from "../../../_lib";

export const dynamic = "force-dynamic";

export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const o = await ownedBuild((await params).id);
  if (!o) return NOT_FOUND();
  const body = (await req.json().catch(() => ({}))) as { serverId?: string; restart?: boolean };
  const serverId = String(body.serverId || "");
  if (!serverId) return NextResponse.json({ error: "Pick a server." }, { status: 400 });
  const rl = checkRateLimit(`mb:install:${o.user.id}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) return NextResponse.json({ error: `Too many requests. Retry in ${rl.retryAfterSec}s.` }, { status: 429 });

  const r = await installBuildToServer(o.build, o.user.id, serverId);
  if (!r.ok) return NextResponse.json({ error: r.error }, { status: 400 });

  let restarted = false;
  let restartNote: string | null = null;
  if (body.restart && r.queued) {
    restartNote = "The install is still queued on the server. Restart from the Mods tab once it shows as installed.";
  } else if (body.restart) {
    const p = await gamePower(serverId, "restart");
    restarted = p.ok;
    if (!p.ok) restartNote = p.error;
  }
  const lastInstall = { serverId, serverName: r.serverName, at: new Date().toISOString(), replaced: r.replaced, backupDir: r.backupDir, restarted };
  await db.modBuild.update({ where: { id: o.build.id }, data: { lastInstall } });
  await db.auditLog.create({ data: { userId: o.user.id, action: "modbuilder.install", detail: `${o.build.id} -> ${serverId} ${r.path}${r.replaced.length ? ` (replaced ${r.replaced.join(", ")}, backup ${r.backupDir})` : ""}` } }).catch(() => {});
  // modId/queued (additive): the Mods tab lists this install under Installed (Cyrus badge).
  return NextResponse.json({ ok: true, path: r.path, replaced: r.replaced, backupDir: r.backupDir, restarted, restartNote, queued: r.queued, modId: r.modId });
}
