export function fileSize(bytes: number | null): string | null {
  if (!bytes || bytes <= 0) return null;
  return bytes >= 1024 ** 3 ? `${(bytes / 1024 ** 3).toFixed(1)} GB` : bytes >= 1024 * 1024 ? `${Math.round(bytes / 1024 / 1024)} MB` : `${Math.max(1, Math.round(bytes / 1024))} KB`;
}

/* Token colours only (text-mint/amber/cyan/rose): measured for both themes. */
const STATE: Record<string, { label: string; cls: string }> = {
  INSTALLED: { label: "Enabled", cls: "border-mint/40 bg-mint/10 text-mint" },
  DISABLED: { label: "Disabled", cls: "border-rim-hi bg-well text-tx-dim" },
  INSTALLING: { label: "Installing", cls: "border-cyan/40 bg-cyan/10 text-cyan" },
  UPDATING: { label: "Updating", cls: "border-cyan/40 bg-cyan/10 text-cyan" },
  ENABLING: { label: "Enabling", cls: "border-cyan/40 bg-cyan/10 text-cyan" },
  DISABLING: { label: "Disabling", cls: "border-amber/40 bg-amber/10 text-amber" },
  REMOVING: { label: "Removing", cls: "border-amber/40 bg-amber/10 text-amber" },
  FAILED: { label: "Failed", cls: "border-rose/40 bg-rose/10 text-rose" },
};
export const PENDING = new Set(["INSTALLING", "UPDATING", "ENABLING", "DISABLING", "REMOVING"]);

/** Newest known version for a row: an on-demand check wins over the stored one. */
export const latestFor = (m: InstalledMod, updates: Record<string, string | null> | null) => (updates && m.id in updates ? updates[m.id] : m.availableVersion);
/** A real, unpinned update exists (Cyrus: a newer version in the chain). */
export function hasUpdateFor(m: InstalledMod, updates: Record<string, string | null> | null): boolean {
  if (m.cyrus) return m.cyrus.updateAvailable;
  const l = latestFor(m, updates);
  return !!l && !!m.version && l !== m.version && !m.pinned;
}

