// ---------------------------------------------------------------------------
// Cyrus v6 lifecycle (2026-10-08, branch feature/cyrus-v6-lifecycle). ADDITIVE ONLY,
// no relations on purpose (rows are keyed by ids, like ModBuild). Writers:
// worker/cyrus-lifecycle.ts and lib/cyrus/lifecycle/server.ts. Design:
// docs/DOCUMENTATION.md "Cyrus mod lifecycle".
// ---------------------------------------------------------------------------

/// One health observation about a Cyrus mod on one server: BROKEN (an error line
/// naming the mod in the game log), CRASH_LOOP (the game kept restarting right after
/// this mod was installed/updated), AUTO_DISABLED (we switched it off because of a
/// crash loop), RECOVERED (it loaded cleanly again). Open = clearedAt null.
model CyrusModSignal {
  id          String    @id @default(cuid())
  serverId    String
  /// GameMod id of the Cyrus mod (ServerMod.modId).
  modId       String
  /// ModBuild chain root (GameMod.sourceId).
  rootBuildId String
  /// The build that was on the server when this was seen (ServerMod.versionId).
  buildId     String?
  /// BROKEN | CRASH_LOOP | AUTO_DISABLED | RECOVERED
  kind        String
  evidence    String?   @db.Text
  /// Game version the server reported when this was seen (null = unknown).
  gameVersion String?
  createdAt   DateTime  @default(now())
  clearedAt   DateTime?

  @@index([serverId, modId, createdAt])
  @@index([rootBuildId, kind, createdAt])
}

/// "Your mod may need an update" for a Cyrus mod's CREATOR. One row per (mod, reason
/// key), so the same warning is never raised twice; `notifiedAt`/`emailedAt` carry
/// the rate limit. Written by the compat watch (setting cyrus_compat_watch_enabled,
/// default off); in dry-run mode rows are written with dryRun=true and nobody is told.
model CyrusCreatorAlert {
  id              String    @id @default(cuid())
  /// The creator (ModBuild.userId of the chain root).
  userId          String
  rootBuildId     String
  /// NEW_GAME_VERSION | SERVERS_AHEAD | ERROR_REPORTS
  kind            String
  /// Dedupe key, e.g. "NEW_GAME_VERSION:minecraft:1.21.11".
  key             String
  gameId          String
  /// The version the creator should build for (null = not one Cyrus can build yet).
  targetVersion   String?
  /// Cyrus can build for targetVersion today ("Update with Cyrus" is offered).
  buildable       Boolean   @default(false)
  title           String
  body            String    @db.Text
  /// Distinct servers behind this alert (installs on newer versions / reporting errors).
  servers         Int       @default(0)
  dryRun          Boolean   @default(false)
  firstSeenAt     DateTime  @default(now())
  lastSeenAt      DateTime  @default(now())
  notifiedAt      DateTime?
  emailedAt       DateTime?
  dismissedAt     DateTime?
  /// Set when the creator shipped a version that covers it (or the cause went away).
  resolvedAt      DateTime?

  @@unique([rootBuildId, key])
  @@index([userId, resolvedAt, dismissedAt])
}
EOF

