/**
 * Which GameSupport the lifecycle reads for a game, and how Cyrus game ids map to the
 * server-side game families (lib/game-config familyFor). PURE, client-safe.
 *
 * MERGE NOTE (additive registry hook): each game agent ships `lib/cyrus/games/<id>.ts`
 * default-exporting a GameSupport. When their branch merges, add ONE import + ONE map entry
 * below. Until then a game with no entry is "not supported by the lifecycle yet", which every
 * caller handles honestly (install offered only where a real installer exists).
 */
import type { GameSupport } from "../games/support";
import minecraft from "../games/minecraft";

export const LIFECYCLE_SUPPORT: Record<string, GameSupport> = {
  minecraft,
  // palworld, terraria, valheim, rust, zomboid: added at merge (see MERGE NOTE).
};

/** Cyrus game id -> server game family (osTemplate.family / familyFor). */
const FAMILY_OF: Record<string, string> = {
  minecraft: "minecraft",
  palworld: "palworld",
  terraria: "terraria",
  valheim: "valheim",
  rust: "rust",
  zomboid: "projectzomboid",
  projectzomboid: "projectzomboid",
};

export const familyOfGame = (gameId: string): string => FAMILY_OF[gameId] ?? gameId;
export const gameOfFamily = (family: string): string =>
  Object.entries(FAMILY_OF).find(([g, f]) => f === family && LIFECYCLE_SUPPORT[g])?.[0] ??
  Object.entries(FAMILY_OF).find(([, f]) => f === family)?.[0] ??
  family;

export function supportFor(gameId: string | null | undefined): GameSupport | null {
  if (!gameId) return null;
  return LIFECYCLE_SUPPORT[gameId] ?? LIFECYCLE_SUPPORT[gameOfFamily(gameId)] ?? null;
}

/** Versions Cyrus can build for on this game (current + supported + legacy), newest first. */
export function buildableVersions(s: GameSupport): string[] {
  return s.versions.filter((v) => v.status !== "unsupported" && !v.version.endsWith(".x")).map((v) => v.version);
}

/** The version Cyrus treats as current for this game (null = none declared). */
export function currentVersion(s: GameSupport): string | null {
  return s.versions.find((v) => v.status === "current")?.version ?? buildableVersions(s)[0] ?? null;
}
EOF

