/**
 * Version compatibility for a Cyrus mod on one server (PURE, client-safe).
 *
 *  - block: the server's game version is one Cyrus marks unsupported (or older than anything
 *           Cyrus builds for), or the mod was built for a different, newer version line than
 *           the server runs. Install is refused.
 *  - warn:  legacy version, server version unknown, mod built for a different version in the
 *           same line, or the server is NEWER than anything the mod was built for. Install needs
 *           the customer to tick the warning.
 *  - ok:    exact match on a current/supported version.
 *
 * "Outdated" is separate from the verdict: the server's game moved past the mod's newest build
 * (game-ahead), or Cyrus can build for a newer version than the mod's newest build (cyrus-ahead).
 */
import type { GameSupport, GameVersionRule } from "../games/support";
import { buildableVersions, currentVersion } from "./support";

/* ── version strings ─────────────────────────────────────────────────────── */

/** Numeric-ish segments of a version label: "1.21.4" -> [1,21,4]; "Build 42.3" -> [42,3]; "v0.4.x" -> [0,4]. */
export function versionParts(v: string): number[] {
  const core = v.trim().replace(/^(v|build\s*)/i, "").split(/[-+ ]/)[0];
  return core.split(".").filter((p) => /^\d+$/.test(p)).map(Number);
}
const isPre = (v: string) => /-(rc|pre|beta|alpha|snapshot)/i.test(v);

/** -1 / 0 / 1. Missing trailing segments count as 0 ("1.21" == "1.21.0"); a pre-release sorts before its release. */
export function compareVersions(a: string, b: string): number {
  const x = versionParts(a), y = versionParts(b);
  for (let i = 0; i < Math.max(x.length, y.length); i++) {
    const d = (x[i] ?? 0) - (y[i] ?? 0);
    if (d) return d < 0 ? -1 : 1;
  }
  if (isPre(a) !== isPre(b)) return isPre(a) ? -1 : 1;
  return 0;
}

/** "1.21.4" and "1.21.11" share the line "1.21"; "26.1.2" is line "26.1". */
export const versionLine = (v: string) => versionParts(v).slice(0, 2).join(".");

export const newestVersion = (vs: string[]): string | null => (vs.length ? [...vs].sort((a, b) => compareVersions(b, a))[0] : null);
export const oldestVersion = (vs: string[]): string | null => (vs.length ? [...vs].sort(compareVersions)[0] : null);

/** The rule a version falls under: exact label, else a ".x" wildcard ("1.20.x" covers 1.20 and 1.20.6). */
export function ruleFor(support: GameSupport, version: string): GameVersionRule | null {
  const exact = support.versions.find((r) => !r.version.endsWith(".x") && compareVersions(r.version, version) === 0 && r.version === version);
  if (exact) return exact;
  const eq = support.versions.find((r) => !r.version.endsWith(".x") && compareVersions(r.version, version) === 0);
  if (eq) return eq;
  return (
    support.versions.find((r) => {
      if (!r.version.endsWith(".x")) return false;
      const pre = versionParts(r.version.slice(0, -2));
      const got = versionParts(version);
      return pre.length > 0 && pre.every((n, i) => got[i] === n);
    }) ?? null
  );
}

/* ── the check ───────────────────────────────────────────────────────────── */

export type CompatLevel = "ok" | "warn" | "block";
export type CompatReason = { code: string; level: CompatLevel; text: string };
export type OutdatedReason = { code: "game-ahead" | "cyrus-ahead" | "newer-build"; text: string; targetVersion: string | null };

export type CompatResult = {
  level: CompatLevel;
  reasons: CompatReason[];
  /** The server runs a version newer than every version this mod was built for. */
  newerThanTested: boolean;
};

export type CompatInput = {
  support: GameSupport;
  /** What the server runs (pinned config / its log). null = we couldn't tell. */
  serverVersion: string | null;
  /** Game version the build being installed targets (ModBuild.mcVersion). */
  target: string;
  /** Every game version any finished build of this mod targets (for "newer than tested"). */
  builtFor: string[];
};

const worst = (rs: CompatReason[]): CompatLevel => (rs.some((r) => r.level === "block") ? "block" : rs.some((r) => r.level === "warn") ? "warn" : "ok");

export function checkCompat(i: CompatInput): CompatResult {
  const game = i.support.name;
  const reasons: CompatReason[] = [];
  const tested = i.builtFor.length ? i.builtFor : [i.target];
  const newestTested = newestVersion(tested)!;
  const sv = i.serverVersion?.trim() || null;
  if (!sv) {
    reasons.push({ code: "server-version-unknown", level: "warn", text: `We couldn't read which ${game} version this server runs. This mod was built for ${i.target}; check the console after the restart.` });
    return { level: worst(reasons), reasons, newerThanTested: false };
  }
  const rule = ruleFor(i.support, sv);
  const buildable = buildableVersions(i.support);
  const oldest = oldestVersion(buildable);
  const current = currentVersion(i.support);

  if (rule?.status === "unsupported") {
    reasons.push({ code: "server-unsupported", level: "block", text: `${game} ${sv} isn't supported by Cyrus mods.${rule.breaking?.length ? " " + rule.breaking[0] : ""} Move the server to ${current ?? "a supported version"} first.` });
  } else if (!rule && oldest && compareVersions(sv, oldest) < 0) {
    reasons.push({ code: "server-too-old", level: "block", text: `${game} ${sv} is older than anything Cyrus builds for (oldest: ${oldest}). Move the server to ${current ?? oldest} first.` });
  } else if (rule?.status === "legacy") {
    reasons.push({ code: "server-legacy", level: "warn", text: `${game} ${sv} is an older version Cyrus still builds for, but it gets less testing. Newer versions are safer.` });
  }

  const cmp = compareVersions(i.target, sv);
  if (cmp > 0) {
    const sameLine = versionLine(i.target) === versionLine(sv);
    reasons.push(
      sameLine
        ? { code: "built-for-newer", level: "warn", text: `This version was built for ${game} ${i.target}, newer than your server's ${sv}. It may call things ${sv} doesn't have and fail to enable.` }
        : { code: "built-for-newer-line", level: "block", text: `This version was built for ${game} ${i.target}; your server runs ${sv}. It won't load across that gap. Build it for ${sv} in Cyrus, or update the server.` },
    );
  } else if (cmp < 0) {
    reasons.push({ code: "built-for-older", level: "warn", text: `Built for ${game} ${i.target}; your server runs ${sv}. Plugins usually carry across minor versions, but check the console after the restart.` });
  }

  const newerThanTested = compareVersions(sv, newestTested) > 0;
  if (newerThanTested && current && compareVersions(sv, current) > 0) {
    reasons.push({ code: "server-ahead-of-cyrus", level: "warn", text: `${game} ${sv} is newer than anything Cyrus can build for yet (newest: ${current}). It may work; nobody has tested it on ${sv}.` });
  }
  return { level: worst(reasons), reasons, newerThanTested };
}

/** Why this installed mod is out of date (empty = it isn't). */
export function outdatedReasons(i: {
  support: GameSupport;
  serverVersion: string | null;
  /** Game versions the mod's finished builds target. */
  builtFor: string[];
  /** The installed build's target version. */
  installedTarget: string | null;
  /** A newer version of the mod exists in its chain (label), else null. */
  newerBuild: string | null;
}): OutdatedReason[] {
  const out: OutdatedReason[] = [];
  const game = i.support.name;
  const newestTested = newestVersion(i.builtFor);
  const current = currentVersion(i.support);
  const sv = i.serverVersion;
  if (sv && newestTested && compareVersions(sv, newestTested) > 0) {
    const canBuild = buildableVersions(i.support).some((v) => compareVersions(v, sv) === 0);
    out.push({
      code: "game-ahead",
      text: `Your server runs ${game} ${sv}; the newest version of this mod was built for ${newestTested}.${canBuild ? " Cyrus can build it for " + sv + "." : " Cyrus can't build for " + sv + " yet."}`,
      targetVersion: canBuild ? sv : null,
    });
  }
  if (i.newerBuild) out.push({ code: "newer-build", text: `${i.newerBuild} of this mod is out.`, targetVersion: null });
