const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, "");
const mentions = (line: string, m: HealthMod) => {
  const l = norm(line);
  return nameForms(m).some((f) => l.includes(f));
};

/** The LAST game version the log reports (a log can span restarts). Minecraft only today. */
export function gameVersionFromLog(family: string, log: string): string | null {
  if (family !== "minecraft") return null;
  const all = [...log.matchAll(/Starting minecraft server version ([0-9][0-9A-Za-z.\-+]*)/g)];
  return all.length ? all[all.length - 1][1].trim() : null;
}

export type CyrusLogVerdict = {
  mod: HealthMod;
  /** loaded = load line seen and no error naming it; broken = an error names it; unknown = can't tell. */
  status: "loaded" | "broken" | "not-seen" | "unknown";
  /** The error looks like a version/API mismatch (out of date for this game version). */
  apiMismatch: boolean;
  evidence: string[];
};

/**
 * Every line that names the mod and looks like an error, plus the load verdict from
 * lib/mod-health.ts. Stack traces: an API-mismatch line within 6 lines AFTER a line naming
 * the mod counts as that mod's (Paper prints the plugin line, then the exception).
 */
export function judgeCyrusLog(input: { family: string; variant: string | null; mods: HealthMod[]; log: string }): CyrusLogVerdict[] {
  const pat = LOG_PATTERNS[input.family];
  const base = judgeModHealth({ family: input.family, variant: input.variant, mods: input.mods, log: input.log });
  const lines = input.log.split(/\r?\n/);
  return input.mods.map((mod) => {
    const v = base.verdicts.find((x) => x.mod === mod);
    const evidence: string[] = [];
    let apiMismatch = false;
    if (pat) {
      lines.forEach((line, i) => {
        const isErr = pat.runtime.some((r) => r.test(line)) || pat.apiMismatch.some((r) => r.test(line)) || pat.fatal.some((r) => r.test(line));
        if (!isErr || !mentions(line, mod)) return;
        evidence.push(line.trim().slice(0, 240));
        const tail = lines.slice(i, i + 7);
        if (tail.some((t) => pat.apiMismatch.some((r) => r.test(t)))) apiMismatch = true;
      });
    }
    if (v?.status === "error" && v.evidence && !evidence.includes(v.evidence)) evidence.unshift(v.evidence);
    const broken = evidence.length > 0;
    if (broken && !apiMismatch && pat) apiMismatch = evidence.some((e) => pat.apiMismatch.some((r) => r.test(e)));
    const status: CyrusLogVerdict["status"] = broken ? "broken" : v?.status === "loaded" ? "loaded" : v?.status === "not-seen" ? "not-seen" : "unknown";
    return { mod, status, apiMismatch: broken && apiMismatch, evidence: evidence.slice(0, 5) };
  });
}

export type CrashLoopVerdict = {
  crashLoop: boolean;
  /** Boots seen in the log since the change. */
  starts: number;
  /** The game finished starting after the LAST boot. */
  readyAfterLast: boolean;
  /** The mod we may blame (null = we can't pin it on one). */
  suspect: HealthMod | null;
  why: string;
  evidence: string[];
};

/**
 * Crash loop right after a change: at least `minStarts` boots in the log since the change and
 * the last one never got to "ready", or the runtime says the container is restarting/crashed.
 * `changed` are the mods installed/updated in the window (Cyrus and others).
 */
export function judgeCrashLoop(input: {
  family: string;
  log: string;
  changed: HealthMod[];
  runtimeState: string | null;
  containerState: string | null;
  minStarts?: number;
}): CrashLoopVerdict {
  const pat = LOG_PATTERNS[input.family];
  const min = input.minStarts ?? 2;
  if (!pat) return { crashLoop: false, starts: 0, readyAfterLast: false, suspect: null, why: "No log patterns for this game.", evidence: [] };
  const lines = input.log.split(/\r?\n/);
  const startIdx = lines.map((l, i) => (pat.start.test(l) ? i : -1)).filter((i) => i >= 0);
  const last = startIdx.length ? startIdx[startIdx.length - 1] : -1;
  const readyAfterLast = last >= 0 && lines.slice(last).some((l) => pat.ready.test(l));
  const runtimeDown = input.containerState === "restarting" || input.runtimeState === "crashed";
  const crashLoop = (startIdx.length >= min && !readyAfterLast) || (runtimeDown && startIdx.length >= 1 && !readyAfterLast);
  if (!crashLoop) return { crashLoop: false, starts: startIdx.length, readyAfterLast, suspect: null, why: readyAfterLast ? "The game finished starting." : "Not enough restarts to call it a loop.", evidence: [] };
  // Who: an error line naming exactly one changed mod; else the only changed mod.
  const errLines = lines.filter((l) => pat.runtime.some((r) => r.test(l)) || pat.fatal.some((r) => r.test(l)) || pat.apiMismatch.some((r) => r.test(l)));
  const named = input.changed.filter((m) => errLines.some((l) => mentions(l, m)));
  if (named.length === 1) {
    const ev = errLines.filter((l) => mentions(l, named[0])).slice(-3).map((l) => l.trim().slice(0, 240));
    return { crashLoop, starts: startIdx.length, readyAfterLast, suspect: named[0], why: `The game restarted ${startIdx.length} times and the errors name ${named[0].name}.`, evidence: ev };
  }
  if (named.length === 0 && input.changed.length === 1) {
    return { crashLoop, starts: startIdx.length, readyAfterLast, suspect: input.changed[0], why: `The game restarted ${startIdx.length} times right after ${input.changed[0].name} was the only mod changed.`, evidence: errLines.slice(-3).map((l) => l.trim().slice(0, 240)) };
  }
  return { crashLoop, starts: startIdx.length, readyAfterLast, suspect: null, why: named.length > 1 ? `The errors name several mods (${named.map((m) => m.name).join(", ")}).` : "Several mods changed and none is named in the errors.", evidence: errLines.slice(-3).map((l) => l.trim().slice(0, 240)) };
}

