/**
 * The lifecycle state of a Cyrus mod on one server (PURE, client-safe).
 *
 * The DB row (ServerMod.status) says what the ENGINE did; this adds what the customer needs to
 * know on top: does it need a restart, did it break, is it out of date. One function derives the
 * state everyone shows (Mods tab row, server card, server banner, NxLabs "On my servers"), and
 * one transition table documents and tests how it moves (docs/DOCUMENTATION.md has the diagram).
 *
 *   resting:   enabled · disabled · pending_restart · failed · broken · outdated
 *   in flight: installing · updating · enabling · disabling · removing
 *
 * Priority when several are true: in flight > failed > broken > disabled > pending_restart >
 * outdated > enabled. ("Broken" outranks "Disabled" only while it is still switched on: a mod we
 * auto-disabled is Disabled, with the reason.)
 */
import type { OutdatedReason } from "./compat";

export type LifecycleState =
  | "installing" | "updating" | "enabling" | "disabling" | "removing"
  | "enabled" | "disabled" | "pending_restart" | "failed" | "broken" | "outdated";

export type LifecycleAction = "enable" | "disable" | "update" | "rollback" | "restart" | "remove" | "retry" | "rebuild";

export type LifecycleInput = {
  /** ServerMod.status */
  status: string;
  /** ServerMod.error (the last failure). */
  error: string | null;
  /** The last mod job changed this mod and the game hasn't restarted since. */
  restartPending: boolean;
  /** Open BROKEN signal / a load verdict "error" for the installed build. */
  broken: { evidence: string | null; apiMismatch: boolean } | null;
  /** We switched it off ourselves (crash loop after install). */
  autoDisabled: { why: string } | null;
  outdated: OutdatedReason[];
  /** The previous version is still on the server after a failed update (engine rolled back). */
  rolledBack: boolean;
};

export type LifecycleView = {
  state: LifecycleState;
  label: string;
  tone: "ok" | "info" | "warn" | "bad" | "muted";
  /** Customer-facing sentences, most important first. */
  notes: string[];
  actions: LifecycleAction[];
};

const FLIGHT: Record<string, LifecycleState> = { INSTALLING: "installing", UPDATING: "updating", ENABLING: "enabling", DISABLING: "disabling", REMOVING: "removing" };

export const STATE_LABEL: Record<LifecycleState, string> = {
  installing: "Installing", updating: "Updating", enabling: "Enabling", disabling: "Disabling", removing: "Removing",
  enabled: "Enabled", disabled: "Disabled", pending_restart: "Pending restart", failed: "Failed", broken: "Broken", outdated: "Outdated",
};

export function deriveLifecycle(i: LifecycleInput): LifecycleView {
  const flight = FLIGHT[i.status];
  if (flight) return { state: flight, label: STATE_LABEL[flight], tone: "info", notes: [], actions: [] };

  if (i.status === "FAILED") {
    return {
      state: "failed", label: "Failed", tone: "bad",
      notes: [i.error ?? "The last change didn't go through.", "Nothing half-installed was left behind: the engine rolls back a write that fails."],
      actions: ["retry", "remove"],
    };
  }

  const on = i.status === "INSTALLED";
  const notes: string[] = [];
  if (i.rolledBack && i.error) notes.push(`The update failed and the previous version was kept: ${i.error}`);

  if (on && i.broken) {
    return {
      state: "broken", label: "Broken", tone: "bad",
      notes: [
        i.broken.apiMismatch
          ? "The game log shows this mod calling something your game version doesn't have: it's out of date for this version."
          : "The game log shows errors naming this mod.",
        ...(i.broken.evidence ? [i.broken.evidence] : []),
        ...notes,
      ],
      actions: ["update", "rollback", "disable", "rebuild"],
    };
  }

  if (i.status === "DISABLED") {
    if (i.autoDisabled) notes.unshift(`We switched it off: ${i.autoDisabled.why} Its config and data were kept.`);
    return { state: "disabled", label: "Disabled", tone: "muted", notes, actions: ["enable", "update", "remove"] };
  }

  if (on && i.restartPending) {
    return { state: "pending_restart", label: "Pending restart", tone: "info", notes: ["Restart the server to load this change.", ...notes], actions: ["restart", "disable"] };
  }

  if (on && i.outdated.length) {
    return {
      state: "outdated", label: "Outdated", tone: "warn",
      notes: [...i.outdated.map((o) => o.text), ...notes],
      actions: i.outdated.some((o) => o.code === "newer-build") ? ["update", "disable"] : ["rebuild", "disable"],
    };
  }

  return { state: "enabled", label: "Enabled", tone: "ok", notes, actions: ["disable", "update", "remove"].filter((a) => a !== "update") as LifecycleAction[] };
}

/* ── transition table (documentation + tests; the engine/worker do the moving) ── */

export type LifecycleEvent =
  | "install" | "update" | "enable" | "disable" | "remove"
  | "job_ok_restart" | "job_ok_hot" | "job_failed" | "update_failed_rolled_back"
  | "restarted" | "log_error" | "crash_loop" | "log_clean" | "game_ahead" | "newer_build";

export const TRANSITIONS: Record<LifecycleState, Partial<Record<LifecycleEvent, LifecycleState>>> = {
  installing: { job_ok_restart: "pending_restart", job_ok_hot: "enabled", job_failed: "failed" },
  updating: { job_ok_restart: "pending_restart", job_ok_hot: "enabled", job_failed: "failed", update_failed_rolled_back: "enabled" },
  enabling: { job_ok_restart: "pending_restart", job_ok_hot: "enabled", job_failed: "failed" },
  disabling: { job_ok_restart: "disabled", job_ok_hot: "disabled", job_failed: "enabled" },
  removing: { job_failed: "enabled" },
  enabled: { disable: "disabling", update: "updating", remove: "removing", log_error: "broken", crash_loop: "disabling", game_ahead: "outdated", newer_build: "outdated" },
  pending_restart: { restarted: "enabled", log_error: "broken", crash_loop: "disabling", disable: "disabling" },
  outdated: { update: "updating", disable: "disabling", remove: "removing", log_error: "broken", crash_loop: "disabling" },
  broken: { update: "updating", disable: "disabling", remove: "removing", log_clean: "enabled", crash_loop: "disabling" },
  disabled: { enable: "enabling", remove: "removing", update: "updating" },
  failed: { install: "installing", remove: "removing" },
};

/** Next state for an event, or null when the event can't happen in that state. */
export function nextState(s: LifecycleState, e: LifecycleEvent): LifecycleState | null {
  return TRANSITIONS[s][e] ?? null;
}

