/**
 * Warnings for a Cyrus mod's CREATOR (PURE): "your mod may need an update for Minecraft X".
 * The compat watch (worker/cyrus-lifecycle.ts) gathers the facts and calls these.
 *
 * Three reasons, each with a stable dedupe key so the same warning is raised once:
 *   NEW_GAME_VERSION  Cyrus can now build for a newer game version than the mod's newest build,
 *                     and the mod matters to someone (published, or installed on a server).
 *   SERVERS_AHEAD     servers that run the mod are on a game version newer than its newest build.
 *   ERROR_REPORTS     the mod's newest version reports errors on 2+ different servers (7 days).
 * A key that no longer applies (the creator built for that version, the errors stopped) is
 * resolved, never re-sent. Rate limits are in `notifyDecision`.
 */
import type { GameSupport } from "../games/support";
import { buildableVersions, currentVersion } from "./support";
import { compareVersions, newestVersion, versionLine } from "./compat";

export type CreatorAlertKind = "NEW_GAME_VERSION" | "SERVERS_AHEAD" | "ERROR_REPORTS";

export type CreatorAlertDraft = {
  kind: CreatorAlertKind;
  key: string;
  targetVersion: string | null;
  buildable: boolean;
  title: string;
  body: string;
  servers: number;
};

export type ChainFacts = {
  gameId: string;
  title: string;
  /** Game versions every finished build targets. */
  builtFor: string[];
  /** Newest finished build id (ERROR_REPORTS is keyed per version). */
  newestBuildId: string;
  published: boolean;
  installs: { serverId: string; serverVersion: string | null }[];
  /** Distinct servers with an open BROKEN signal on the newest build in the last 7 days. */
  erroringServers: number;
  apiMismatchServers: number;
};

export const ERROR_SERVER_THRESHOLD = 2;

export function creatorAlertsFor(support: GameSupport, c: ChainFacts): CreatorAlertDraft[] {
  const out: CreatorAlertDraft[] = [];
  const g = support.name;
  const newest = newestVersion(c.builtFor);
  if (!newest) return out;
  const buildable = buildableVersions(support);
  const canBuild = (v: string) => buildable.some((b) => compareVersions(b, v) === 0);
  const current = currentVersion(support);

  if (current && compareVersions(current, newest) > 0 && (c.published || c.installs.length > 0)) {
    out.push({
      kind: "NEW_GAME_VERSION",
      key: `NEW_GAME_VERSION:${c.gameId}:${current}`,
      targetVersion: current,
      buildable: true,
      title: `${c.title} may need an update for ${g} ${current}`,
      body: `Your newest version of ${c.title} was built for ${g} ${newest}. Cyrus can now build for ${current}. Rebuilding for it is usually a small change and keeps every feature.`,
      servers: c.installs.length,
    });
  }

  const ahead = c.installs.filter((i) => i.serverVersion && compareVersions(i.serverVersion, newest) > 0);
  if (ahead.length) {
    const top = newestVersion(ahead.map((i) => i.serverVersion!))!;
    const ok = canBuild(top);
    out.push({
      kind: "SERVERS_AHEAD",
      key: `SERVERS_AHEAD:${c.gameId}:${versionLine(top)}`,
      targetVersion: ok ? top : null,
      buildable: ok,
      title: `${ahead.length === 1 ? "A server" : `${ahead.length} servers`} running ${c.title} moved to ${g} ${top}`,
      body: ok
        ? `${c.title} was last built for ${g} ${newest}, but ${ahead.length === 1 ? "a server runs" : "servers run"} it on ${top}. Build a version for ${top} so it keeps loading.`
        : `${c.title} was last built for ${g} ${newest}, but ${ahead.length === 1 ? "a server runs" : "servers run"} it on ${top}. Cyrus can't build for ${top} yet; we'll tell you when it can.`,
      servers: ahead.length,
    });
  }

  if (c.erroringServers >= ERROR_SERVER_THRESHOLD) {
    const mismatch = c.apiMismatchServers >= Math.ceil(c.erroringServers / 2);
    out.push({
      kind: "ERROR_REPORTS",
      key: `ERROR_REPORTS:${c.newestBuildId}`,
      targetVersion: mismatch && current ? current : null,
      buildable: mismatch && !!current,
      title: `${c.title} is reporting errors on ${c.erroringServers} servers`,
      body: mismatch
        ? `The errors look like a game-version mismatch (the mod calls things the game no longer has). Rebuilding it for ${g} ${current} usually fixes it.`
        : "The game logs on several servers show errors naming your mod. Open it in Cyrus and ask it to fix the error; the log lines are on each server's Mods tab.",
      servers: c.erroringServers,
    });
  }
  return out;
}

/* ── rate limit ─────────────────────────────────────────────────────────── */

export const EMAILS_PER_CREATOR_PER_WEEK = 2;

export function notifyDecision(i: {
  alert: { notifiedAt: Date | null; emailedAt: Date | null; dismissedAt: Date | null; resolvedAt: Date | null };
  dryRun: boolean;
  /** Creator alert emails we sent this creator in the last 7 days. */
  emailsThisWeek: number;
  /** The creator's email preference allows it (lib/prefs.ts mayDeliverTo). Checked by sendMail too. */
  emailAllowed: boolean;
}): { inapp: boolean; email: boolean; why: string } {
  const a = i.alert;
  if (i.dryRun) return { inapp: false, email: false, why: "dry run" };
  if (a.dismissedAt || a.resolvedAt) return { inapp: false, email: false, why: a.dismissedAt ? "dismissed" : "resolved" };
  const inapp = !a.notifiedAt;
  const email = !a.emailedAt && i.emailAllowed && i.emailsThisWeek < EMAILS_PER_CREATOR_PER_WEEK;
  return { inapp, email, why: email ? "first time" : !i.emailAllowed ? "email off in preferences" : a.emailedAt ? "already emailed" : i.emailsThisWeek >= EMAILS_PER_CREATOR_PER_WEEK ? "weekly email limit" : "already notified" };
}

/** Where "Update with Cyrus for the new version" goes: the project, refine path, version preselected. */
export function updateWithCyrusHref(buildId: string, targetVersion: string | null): string {
  return `/dashboard/cyrus/${encodeURIComponent(buildId)}${targetVersion ? `?retarget=${encodeURIComponent(targetVersion)}` : ""}`;
}

