 */
export async function toPageView(page: CyrusModPage, viewer: { id: string; role?: string | null } | null): Promise<PageView | null> {
  const doc = readModDoc(page.doc);
  if (!doc) return null;
  const [creator, forkOf, forks, open, bugsOpen, total] = await Promise.all([
    db.user.findUnique({ where: { id: page.userId }, select: { name: true } }),
    page.forkOfPageId ? db.cyrusModPage.findUnique({ where: { id: page.forkOfPageId }, select: { slug: true, title: true, visibility: true, hiddenAt: true, userId: true } }) : null,
    db.cyrusFork.count({ where: { sourcePageId: page.id } }),
    db.cyrusModPost.count({ where: { pageId: page.id, parentId: null, status: "OPEN", hiddenAt: null } }),
    db.cyrusModPost.count({ where: { pageId: page.id, parentId: null, status: "OPEN", kind: "BUG", hiddenAt: null } }),
    db.cyrusModPost.count({ where: { pageId: page.id, parentId: null, hiddenAt: null } }),
  ]);
