/**
 * Cyrus mod lifecycle: the DB-backed half (server-only; no next/* imports, so the worker and
 * the portal both use it). The pure rules live next door (state/compat/install-plan/creator).
 *
 * What it answers:
 *   - lifecycleForServer(serverId): every Cyrus mod on a server with its lifecycle state
 *     (Enabled / Disabled / Pending restart / Failed / Broken / Outdated + why);
 *   - summariesForServers(ids): the counts the server card and banner show;
 *   - installPlansFor(build, actor): the install plan for each of the actor's servers;
 *   - publicInstallAllowed(): may someone install another creator's PUBLISHED version.
 */
import type { ModBuild, Server, ServerMod, GameMod } from "@prisma/client";
import { db } from "../../db";
import { familyFor } from "../../game-config";
import { pinnedVersion } from "../../mods/facts";
import { CYRUS_SOURCE, CYRUS_VARIANTS } from "../../mods/installers/cyrus";
import { currentVersion as chainHead, succeededVersions, versionLabel } from "../../cyrus-mods/doc";
import { cyrusModsPublicEnabled } from "../../cyrus-mods/gate";
import { outdatedReasons, checkCompat } from "./compat";
import { deriveLifecycle, type LifecycleView } from "./state";
import { buildInstallPlan, type InstallPlan, type PlanServer } from "./install-plan";
import { supportFor } from "./support";

type HealthPlan = { startedAt?: string; gameVersion?: string | null; cyrus?: { modId: string; buildId: string | null; status: string; apiMismatch: boolean; evidence: string[] }[] };

const safetyOf = (b: Pick<ModBuild, "result">): "pass" | "warn" | "block" | null => {
  const v = (b.result as { safety?: { verdict?: string } } | null)?.safety?.verdict;
  return v === "pass" || v === "warn" || v === "block" ? v : null;
};

/** The game version a server runs: its pinned config, else what the last log read reported. */
export async function serverGameVersion(server: Pick<Server, "id" | "gameConfig">): Promise<string | null> {
  const pinned = pinnedVersion(server.gameConfig);
  if (pinned) return pinned;
  const run = await db.modUpdateRun.findFirst({ where: { serverId: server.id, trigger: "health" }, orderBy: { startedAt: "desc" }, select: { plan: true } }).catch(() => null);
