export async function lifecycleRows(server: Server & { osTemplate: { family: string } | null }, rows: (ServerMod & { mod: GameMod })[]): Promise<CyrusLifecycleRow[]> {
  const cy = rows.filter((r) => r.mod.source === CYRUS_SOURCE && r.mod.sourceId);
  if (!cy.length) return [];
  const family = familyFor(server as never) ?? server.osTemplate?.family ?? "minecraft";
  const support = supportFor(family);
  const [chains, pending, signals, health, serverVersion] = await Promise.all([
    chainsFor([...new Set(cy.map((r) => r.mod.sourceId!))]),
    restartPendingFor(server.id),
    db.cyrusModSignal.findMany({ where: { serverId: server.id, modId: { in: cy.map((r) => r.modId) }, clearedAt: null }, orderBy: { createdAt: "desc" } }).catch(() => []),
    db.modUpdateRun.findFirst({ where: { serverId: server.id, trigger: "health" }, orderBy: { startedAt: "desc" }, select: { startedAt: true, plan: true } }).catch(() => null),
    serverGameVersion(server),
  ]);
  const hp = (health?.plan ?? null) as HealthPlan | null;
  return cy.map((r) => {
    const chain = chains.get(r.mod.sourceId!) ?? [];
    const ok = succeededVersions(chain);
    const head = chainHead(chain);
    const label = (id: string | null) => {
      const i = ok.findIndex((b) => b.id === id);
      return i < 0 ? null : versionLabel({ n: i + 1, version: ok[i].version });
    };
    const installed = ok.find((b) => b.id === r.versionId) ?? null;
    const updateAvailable = !!r.versionId && !!head && head.id !== r.versionId;
    const sig = signals.filter((s) => s.modId === r.modId);
    const openBroken = sig.find((s) => s.kind === "BROKEN" && (!s.buildId || s.buildId === r.versionId));
    // A fresh log read after the last change wins over an older signal.
    const fresh = hp?.cyrus?.find((v) => v.modId === r.modId && (!v.buildId || v.buildId === r.versionId));
    const freshAfterChange = !!health && health.startedAt > r.updatedAt;
    const broken = fresh && freshAfterChange && fresh.status === "broken"
      ? { evidence: fresh.evidence[0] ?? null, apiMismatch: fresh.apiMismatch }
      : openBroken && !(fresh && freshAfterChange && fresh.status === "loaded")
        ? { evidence: openBroken.evidence, apiMismatch: /NoSuchMethod|NoSuchField|NoClassDef|UnsupportedClassVersion|Unsupported API/.test(openBroken.evidence ?? "") }
        : null;
    const auto = sig.find((s) => s.kind === "AUTO_DISABLED");
    const outdated = support
      ? outdatedReasons({ support, serverVersion, builtFor: ok.map((b) => b.mcVersion), installedTarget: installed?.mcVersion ?? null, newerBuild: updateAvailable ? label(head!.id) : null })
      : [];
    const view = deriveLifecycle({
      status: r.status,
      error: r.error,
      restartPending: pending.has(r.modId),
      broken,
      autoDisabled: r.status === "DISABLED" && auto ? { why: auto.evidence ?? "the game kept crashing right after it was installed." } : null,
      outdated,
      rolledBack: r.status === "INSTALLED" && !!r.error,
    });
    return {
      modId: r.modId,
      rootBuildId: r.mod.sourceId!,
      name: r.mod.name,
      view,
      installedLabel: label(r.versionId),
      latestLabel: head ? label(head.id) : null,
      latestBuildId: head?.id ?? null,
      updateAvailable,
      autoUpdate: r.autoUpdate === "AUTO",
      serverVersion,
    };
  });
}

export type ServerCyrusSummary = { broken: number; outdated: number; failed: number; pendingRestart: number; autoDisabled: number; total: number; worst: "bad" | "warn" | "info" | null; headline: string | null };

export function summarize(rows: CyrusLifecycleRow[]): ServerCyrusSummary {
  const n = (s: string) => rows.filter((r) => r.view.state === s).length;
  const autoDisabled = rows.filter((r) => r.view.state === "disabled" && r.view.notes[0]?.startsWith("We switched it off")).length;
  const s = { broken: n("broken"), outdated: n("outdated"), failed: n("failed"), pendingRestart: n("pending_restart"), autoDisabled, total: rows.length };
  const worst = s.broken || s.failed || s.autoDisabled ? "bad" : s.outdated ? "warn" : s.pendingRestart ? "info" : null;
  const first = (st: string) => rows.find((r) => r.view.state === st)?.name;
  const headline =
    s.broken ? `${first("broken")}${s.broken > 1 ? ` and ${s.broken - 1} more` : ""} ${s.broken > 1 ? "are" : "is"} reporting errors`
    : s.autoDisabled ? `We switched off ${s.autoDisabled === 1 ? "a Cyrus mod" : `${s.autoDisabled} Cyrus mods`} after the game kept crashing`
    : s.failed ? `A change to ${first("failed")} failed`
    : s.outdated ? `${s.outdated === 1 ? `${first("outdated")} is` : `${s.outdated} Cyrus mods are`} out of date`
    : s.pendingRestart ? "Restart to load your Cyrus mod changes"
    : null;
  return { ...s, worst, headline };
}

/** Per-server summaries for a list of servers (server cards). Servers without Cyrus mods are left out. */
export async function summariesForServers(serverIds: string[]): Promise<Map<string, ServerCyrusSummary>> {
  const out = new Map<string, ServerCyrusSummary>();
  if (!serverIds.length) return out;
  const withCyrus = await db.serverMod.findMany({ where: { serverId: { in: serverIds }, mod: { source: CYRUS_SOURCE } }, select: { serverId: true }, distinct: ["serverId"] });
  for (const { serverId } of withCyrus.slice(0, 40)) {
    const rows = await lifecycleForServer(serverId).catch(() => []);
    if (rows.length) out.set(serverId, summarize(rows));
  }
  return out;
}

