"use server";

/**
 * Cyrus mod lifecycle on the customer's own servers (docs/DOCUMENTATION.md "Cyrus mod lifecycle"):
 * install plans with version checks and the confirm step, install from Cyrus or NxLabs, switch
 * on/off, update one / update all, per-mod auto-update opt-in, and the creator's warnings.
 *
 * Every server change is the normal engine path (ServerMod -> one GAME_MOD_SYNC job under the
 * per-server lock, lib/mods/queue.ts): backup first, staged write, rollback on failure.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { SANDBOX } from "./sandbox";
import { familyFor } from "./game-config";
import { withServerJobLock } from "./job-guard";
import { enqueueModOp } from "./mods/queue";
import { toggleDecision } from "./mods/toggle-policy";
import { engineInstallerFor } from "./mods/installers";
import { CYRUS_SOURCE } from "./mods/installers/cyrus";
import { installBuildToServer } from "./modbuilder/install";
import { cyrusAccessFor } from "./cyrus-mods/gate";
import { gamePower } from "./actions-game-control";
import { confirmPlan } from "./cyrus/lifecycle/install-plan";
import { installPlansFor, lifecycleForServer, publicInstallAllowed, type CyrusLifecycleRow, type ServerPlan } from "./cyrus/lifecycle/server";
import { updateWithCyrusHref } from "./cyrus/lifecycle/creator";

const ID = /^[A-Za-z0-9_-]{1,64}$/;
const live = () => SANDBOX || process.env.ENABLE_REAL_GAMEMODS === "1";

async function installableBuild(buildId: string) {
  const user = await requireUser();
  if (typeof buildId !== "string" || !ID.test(buildId)) return { user, build: null };
  const build = await db.modBuild.findUnique({ where: { id: buildId } });
  if (!build || build.status !== "succeeded" || !build.jarName) return { user, build: null };
  if (build.userId !== user.id) {
    if (!(await cyrusAccessFor(user)).allowed || !(await publicInstallAllowed(build, user.id))) return { user, build: null };
  }
  return { user, build };
}

/** The install plan for every Minecraft server the viewer owns (dialog step 1). */
export async function getCyrusInstallPlans(buildId: string): Promise<{ error?: string; game?: string; plans?: ServerPlan[]; installsLive?: boolean; own?: boolean }> {
  try {
    const { user, build } = await installableBuild(buildId);
    if (!build) return { error: "This version can't be installed." };
    const r = await installPlansFor(build, user.id);
    return { game: r.game, plans: r.plans, installsLive: live(), own: build.userId === user.id };
  } catch {
    return { error: "Couldn't check your servers." };
  }
}

export type CyrusInstallResult = { ok?: true; error?: string; queued?: boolean; restarted?: boolean; restartNote?: string | null; replaced?: string[]; serverName?: string; modId?: string };

/** Install (or update to) this build on one server after the customer confirmed the plan's warnings. */
export async function installCyrusMod(buildId: string, serverId: string, acked: string[], opts: { restart?: boolean } = {}): Promise<CyrusInstallResult> {
  const { user, build } = await installableBuild(buildId);
  if (!build) return { error: "This version can't be installed." };
  if (typeof serverId !== "string" || !ID.test(serverId)) return { error: "Pick a server." };
  const ack = Array.isArray(acked) ? acked.filter((a) => typeof a === "string").slice(0, 20) : [];
  const { plans } = await installPlansFor(build, user.id);
  const sp = plans.find((p) => p.server.id === serverId);
  if (!sp) return { error: "That server isn't one of your Minecraft servers." };
  if (sp.plan.op === "none") return { error: "That version is already on the server." };
  const ok = confirmPlan(sp.plan, ack);
  if (!ok.ok) return { error: ok.error };
  if (!live()) return { error: "One-click mod changes are paused right now, so nothing was installed." };

  const r = await installBuildToServer(build, user.id, serverId, { allowPublic: build.userId !== user.id });
  if (!r.ok) return { error: r.error };
  let restarted = false;
  let restartNote: string | null = null;
  if (opts.restart && sp.plan.restart === "required") {
    if (r.queued) restartNote = "The install is still queued. Restart from the Mods tab once it shows as installed.";
    else {
      const p = await gamePower(serverId, "restart");
      restarted = p.ok;
      if (!p.ok) restartNote = p.error;
    }
  }
  if (build.userId === user.id) {
    await db.modBuild.update({ where: { id: build.id }, data: { lastInstall: { serverId, serverName: r.serverName, at: new Date().toISOString(), replaced: r.replaced, backupDir: r.backupDir, restarted } } }).catch(() => {});
  }
  await db.auditLog.create({ data: { userId: user.id, action: "cyrus.install", detail: `${build.id} -> ${serverId} acked=${ack.join(",")}${build.userId !== user.id ? " (published, other creator)" : ""}`.slice(0, 900) } }).catch(() => {});
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true, queued: r.queued, restarted, restartNote, replaced: r.replaced, serverName: r.serverName, modId: r.modId };
}

async function ownedCyrusRows(serverId: string) {
  const user = await requireUser();
  if (typeof serverId !== "string" || !ID.test(serverId)) throw new Error("Not found");
  const server = await db.server.findUnique({ where: { id: serverId }, include: { osTemplate: true, gamePlan: true } });
  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) throw new Error("Not found");
  return { user, server };
}

/** Lifecycle rows for one server (Mods tab, NxLabs "On my servers"). */
export async function getCyrusLifecycle(serverId: string): Promise<{ error?: string; rows?: CyrusLifecycleRow[] }> {
  try {
    await ownedCyrusRows(serverId);
    return { rows: await lifecycleForServer(serverId) };
  } catch {
    return { error: "Couldn't load your Cyrus mods." };
  }
}

/** Switch a Cyrus mod off (kept on disk, config kept) or back on. */
export async function setCyrusModEnabled(serverId: string, modId: string, on: boolean): Promise<{ ok?: true; error?: string }> {
  let ctx;
  try {
    ctx = await ownedCyrusRows(serverId);
  } catch {
    return { error: "Not found." };
  }
  const { user, server } = ctx;
  if (typeof modId !== "string" || !ID.test(modId)) return { error: "Not found." };
  const row = await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId } }, include: { mod: true } });
  if (!row || row.mod.source !== CYRUS_SOURCE) return { error: "Not found." };
  if (!live()) return { error: "One-click mod changes are paused right now, so nothing was changed." };
  if (server.status !== "RUNNING") return { error: "Start the server's VM first: mods are changed on the running server." };
  const family = familyFor(server) ?? row.mod.gameFamily;
  const d = toggleDecision({ family, variant: server.gameVariant ?? null, mod: row.mod, engine: !!engineInstallerFor(family, row.mod.source) });
  if (!d.allowed) return { error: d.reason };
  if (on && row.status !== "DISABLED") return { error: `${row.mod.name} is already on.` };
  if (!on && row.status !== "INSTALLED") return { error: `${row.mod.name} is ${row.status.toLowerCase()} right now.` };
  const r = await enqueueModOp(serverId, modId, on ? "enable" : "disable", { userId: user.id, slug: row.mod.slug });
  if (!r.ok) return { error: r.error };
  if (on) await db.cyrusModSignal.updateMany({ where: { serverId, modId, kind: "AUTO_DISABLED", clearedAt: null }, data: { clearedAt: new Date() } }).catch(() => {});
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true };
}

/** Update every Cyrus mod with a newer version on this server, in ONE job (config kept, each backed up). */
export async function updateAllCyrusMods(serverId: string): Promise<{ ok?: true; error?: string; count?: number }> {
  let ctx;
  try {
    ctx = await ownedCyrusRows(serverId);
  } catch {
    return { error: "Not found." };
  }
  const { user, server } = ctx;
  if (!live()) return { error: "One-click mod changes are paused right now, so nothing was queued." };
  if (server.status !== "RUNNING") return { error: "Start the server's VM first." };
  const rows = (await lifecycleForServer(serverId)).filter((r) => r.updateAvailable && r.latestBuildId && r.view.state !== "disabled" && !["installing", "updating", "enabling", "disabling", "removing", "failed"].includes(r.view.state));
  if (!rows.length) return { error: "Every Cyrus mod here is on its newest version." };
  // Published versions only for other creators' mods (re-checked by the engine's jar source too).
  const targets: { modId: string; buildId: string; slug: string }[] = [];
  for (const r of rows.slice(0, 25)) {
    const b = await db.modBuild.findUnique({ where: { id: r.latestBuildId! } });
    if (!b || !(await publicInstallAllowed(b, server.userId))) continue;
    const gm = await db.gameMod.findUnique({ where: { id: r.modId }, select: { slug: true } });
    targets.push({ modId: r.modId, buildId: b.id, slug: gm?.slug ?? r.modId });
  }
  if (!targets.length) return { error: "No update can be applied right now." };
  const q = await withServerJobLock(serverId, async (tx) => {
    const inflight = await tx.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
    if (inflight > 0) return { ok: false as const, error: "Another operation is already running on this server. Try again when it finishes." };
    const cur = await tx.serverMod.findMany({ where: { serverId, modId: { in: targets.map((t) => t.modId) } }, select: { modId: true, status: true } });
    if (cur.some((c) => c.status !== "INSTALLED")) return { ok: false as const, error: "A mod changed while you were looking. Refresh and try again." };
    for (const t of targets) await tx.serverMod.update({ where: { serverId_modId: { serverId, modId: t.modId } }, data: { status: "UPDATING", error: null, targetVersionId: t.buildId } });
    const job = await tx.job.create({ data: { type: "GAME_MOD_SYNC", serverId, payload: { ops: targets.map((t) => ({ modId: t.modId, op: "update" })), batch: true, cyrusUpdateAll: true } }, select: { id: true } });
    return { ok: true as const, jobId: job.id };
  });
  if (!q.ok) return { error: q.error };
  await db.auditLog.createMany({ data: targets.map((t) => ({ userId: user.id, action: "gameserver.mod.update", detail: `${serverId} mod=${t.slug} version=${t.buildId} batch=${q.jobId} cyrus-update-all` })) }).catch(() => {});
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true, count: targets.length };
}

/** Per-mod opt-in: apply new versions of this Cyrus mod automatically (the lifecycle sweep does it, server empty, off-peak). */
export async function setCyrusAutoUpdate(serverId: string, modId: string, on: boolean): Promise<{ ok?: true; error?: string }> {
  try {
    await ownedCyrusRows(serverId);
  } catch {
    return { error: "Not found." };
  }
  if (typeof modId !== "string" || !ID.test(modId)) return { error: "Not found." };
  const row = await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId } }, include: { mod: { select: { source: true } } } });
  if (!row || row.mod.source !== CYRUS_SOURCE) return { error: "Not found." };
  await db.serverMod.update({ where: { id: row.id }, data: { autoUpdate: on ? "AUTO" : "OFF" } });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true };
}

/* ── creator warnings ───────────────────────────────────────────────────── */

export type CreatorAlertView = {
  id: string; kind: string; title: string; body: string; servers: number; targetVersion: string | null; buildable: boolean;
  modTitle: string; pageSlug: string | null; updateHref: string | null; firstSeenAt: string; lastSeenAt: string;
};

/** The viewer's open creator warnings (not dismissed, not resolved, not dry-run). */
export async function getMyCreatorAlerts(): Promise<{ error?: string; alerts?: CreatorAlertView[] }> {
  try {
    const user = await requireUser();
    const rows = await db.cyrusCreatorAlert.findMany({ where: { userId: user.id, dismissedAt: null, resolvedAt: null, dryRun: false }, orderBy: { lastSeenAt: "desc" }, take: 20 });
    return { alerts: await toAlertViews(rows) };
  } catch {
    return { error: "Couldn't load your mod warnings." };
  }
}

export async function toAlertViews(rows: Awaited<ReturnType<typeof db.cyrusCreatorAlert.findMany>>): Promise<CreatorAlertView[]> {
  const roots = [...new Set(rows.map((r) => r.rootBuildId))];
  const [pages, heads] = await Promise.all([
    db.cyrusModPage.findMany({ where: { rootBuildId: { in: roots } }, select: { rootBuildId: true, slug: true, title: true, latestBuildId: true } }),
    db.modBuild.findMany({ where: { OR: [{ id: { in: roots } }, { rootBuildId: { in: roots } }], status: "succeeded" }, orderBy: { createdAt: "desc" }, select: { id: true, rootBuildId: true, pluginName: true } }),
  ]);
  return rows.map((r) => {
    const p = pages.find((x) => x.rootBuildId === r.rootBuildId);
    const head = p?.latestBuildId ?? heads.find((h) => (h.rootBuildId ?? h.id) === r.rootBuildId)?.id ?? r.rootBuildId;
    return {
      id: r.id, kind: r.kind, title: r.title, body: r.body, servers: r.servers, targetVersion: r.targetVersion, buildable: r.buildable,
      modTitle: p?.title ?? heads.find((h) => (h.rootBuildId ?? h.id) === r.rootBuildId)?.pluginName ?? "Your Cyrus mod",
      pageSlug: p?.slug ?? null,
      updateHref: r.buildable || r.kind === "ERROR_REPORTS" ? updateWithCyrusHref(head, r.buildable ? r.targetVersion : null) : null,
      firstSeenAt: r.firstSeenAt.toISOString(), lastSeenAt: r.lastSeenAt.toISOString(),
    };
  });
}

export async function dismissCreatorAlert(id: string): Promise<{ ok?: true; error?: string }> {
  const user = await requireUser();
  if (typeof id !== "string" || !ID.test(id)) return { error: "Not found." };
  const r = await db.cyrusCreatorAlert.updateMany({ where: { id, userId: user.id }, data: { dismissedAt: new Date() } });
  return r.count ? { ok: true } : { error: "Not found." };
}

