/**
 * Cyrus mod lifecycle sweeps (docs/DOCUMENTATION.md "Cyrus mod lifecycle"). Two sweeps, both
 * INERT by default and each behind its own Setting (admin: /admin/cyrus-mods):
 *
 *  cyrusLifecycleSweep      Setting cyrus_lifecycle_enabled (default "false")
 *    1. signals: turns the Cyrus verdicts the mod-health log read stores (worker/mod-health.ts,
 *       plan.cyrus) into BROKEN / RECOVERED signals and tells the server owner once per break;
 *    2. crash loop: a Cyrus mod installed/updated in the last 20 min on a server whose game keeps
 *       restarting without finishing its start -> read the log since the change, and when the
 *       evidence pins it on that Cyrus mod, switch it off (engine "disable": the jar moves to
 *       /root/.nxeon-mods/disabled, config kept) and notify. Needs ENABLE_REAL_GAMEMODS=1 (or the
 *       sandbox); never for a mod whose disable could delete world content;
 *    3. auto-update: Cyrus mods the owner opted in (ServerMod.autoUpdate = AUTO) move to their
 *       newest finished, published, not-blocked version, only while nobody is online.
 *
 *  cyrusCompatWatchSweep    Setting cyrus_compat_watch_enabled (default "false"),
 *                           cyrus_compat_watch_dry_run (default "true": record + log, tell nobody)
 *    Creator warnings (lib/cyrus/lifecycle/creator.ts): new game version Cyrus can build for,
 *    servers running the mod on a newer version, errors on 2+ servers. One row per (mod, key),
 *    resolved when it no longer applies, in-app once + email at most 2 per creator per week
 *    (and only where the creator's email preference allows, kind cyrus_creator_alert).
 *
 * Every server write goes through the job queue (lib/mods/queue.ts). Never touches a server that
 * has a job queued or running.
 */
import { db } from "../lib/db";
import { getSettingBool } from "../lib/settings";
import { SANDBOX } from "../lib/sandbox";
import { familyFor } from "../lib/game-config";
import { withServerSsh, exec as sshExec } from "../lib/ssh-exec";
import { enqueueModOp } from "../lib/mods/queue";
import { toggleDecision } from "../lib/mods/toggle-policy";
import { engineInstallerFor } from "../lib/mods/installers";
import { CYRUS_SOURCE } from "../lib/mods/installers/cyrus";
import { currentVersion as chainHead, displayName, succeededVersions } from "../lib/cyrus-mods/doc";
import { judgeCrashLoop } from "../lib/cyrus/lifecycle/logs";
import { checkCompat } from "../lib/cyrus/lifecycle/compat";
import { creatorAlertsFor, notifyDecision, updateWithCyrusHref, type ChainFacts } from "../lib/cyrus/lifecycle/creator";
import { gameOfFamily, supportFor } from "../lib/cyrus/lifecycle/support";
import { publicInstallAllowed, serverGameVersion } from "../lib/cyrus/lifecycle/server";
import { mayDeliverTo } from "../lib/prefs";
import { dockerContainerNameFrom } from "./game-variant";
import { playersOnline } from "./mod-autoupdate";

const CRASH_WINDOW_MS = 20 * 60_000;
const CONTAINER_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,62}$/;
const DOWN_STATES = new Set(["crashed", "not_responding", "game_stopped", "starting"]);
const realChanges = () => SANDBOX || process.env.ENABLE_REAL_GAMEMODS === "1";

type Mailer = (opts: { to: string; subject: string; html: string; userId: string; kind: "mod_health" | "cyrus_creator_alert" }) => Promise<boolean>;
async function defaultMailer(): Promise<Mailer> {
  const { sendMail, layout, button } = await import("../lib/mailer");
  void layout;
  void button;
  return (o) => sendMail(o);
}

const esc = (s: string) => s.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);

async function emailHtml(title: string, body: string, href: string, cta: string): Promise<string> {
  const { wrapEmail, emailHeading, emailParagraph, emailButton, emailNote, appUrl } = await import("../lib/email-render");
  return wrapEmail(
    emailHeading(title) + emailParagraph(esc(body)) + emailButton(`${appUrl()}${href}`, cta) +
      emailNote("You get this because you build mods with Cyrus on Nxeon. Turn these emails off under Account → Notifications (activity email)."),
  );
}

let lifecycleRunning = false;
let watchRunning = false;

/* ═══ 1-3: the server-side sweep ═══════════════════════════════════════════ */

export async function cyrusLifecycleSweep(opts: { force?: boolean; mailer?: Mailer; log?: (s: string) => void } = {}): Promise<{ signals: number; autoDisabled: number; autoUpdated: number }> {
  const out = { signals: 0, autoDisabled: 0, autoUpdated: 0 };
  if (lifecycleRunning) return out;
  if (!opts.force && !(await getSettingBool("cyrus_lifecycle_enabled", false))) return out;
  lifecycleRunning = true;
  const log = opts.log ?? ((s: string) => console.log(`[cyrus-lifecycle] ${s}`));
  const mail = opts.mailer ?? (await defaultMailer());
  try {
    out.signals = await signalsFromHealth(mail, log);
    out.autoDisabled = await crashLoops(mail, log);
    out.autoUpdated = await autoUpdates(log);
  } finally {
    lifecycleRunning = false;
  }
  return out;
}

type HealthCyrus = { modId: string; buildId: string | null; status: string; apiMismatch: boolean; evidence: string[] };

/** Health runs of the last hour that read Cyrus mods -> BROKEN / RECOVERED signals. */
async function signalsFromHealth(mail: Mailer, log: (s: string) => void): Promise<number> {
  const runs = await db.modUpdateRun.findMany({ where: { trigger: "health", startedAt: { gt: new Date(Date.now() - 3600_000) } }, orderBy: { startedAt: "asc" }, take: 200 });
  let n = 0;
  for (const run of runs) {
    const plan = (run.plan ?? {}) as { cyrus?: HealthCyrus[]; gameVersion?: string | null };
    for (const v of plan.cyrus ?? []) {
      const open = await db.cyrusModSignal.findFirst({ where: { serverId: run.serverId, modId: v.modId, kind: "BROKEN", clearedAt: null } });
      if (v.status === "broken") {
        if (open && open.buildId === v.buildId) continue;
        if (open) await db.cyrusModSignal.update({ where: { id: open.id }, data: { clearedAt: new Date() } });
        const gm = await db.gameMod.findUnique({ where: { id: v.modId }, select: { name: true, sourceId: true } });
        if (!gm?.sourceId) continue;
        await db.cyrusModSignal.create({ data: { serverId: run.serverId, modId: v.modId, rootBuildId: gm.sourceId, buildId: v.buildId, kind: "BROKEN", evidence: v.evidence.join("\n").slice(0, 2000) || null, gameVersion: plan.gameVersion ?? null } });
        n++;
        await tellOwner(run.serverId, `${gm.name} is reporting errors`, `${v.apiMismatch ? "The game log shows it calling something this game version doesn't have, so it's out of date for this version." : "The game log shows errors naming it."} Open the Mods tab to update, roll back or switch it off.`, mail);
        log(`BROKEN ${gm.name} on ${run.serverId}`);
      } else if (v.status === "loaded" && open && run.startedAt > open.createdAt) {
        await db.cyrusModSignal.update({ where: { id: open.id }, data: { clearedAt: new Date() } });
        await db.cyrusModSignal.create({ data: { serverId: run.serverId, modId: v.modId, rootBuildId: open.rootBuildId, buildId: v.buildId, kind: "RECOVERED", gameVersion: plan.gameVersion ?? null, clearedAt: new Date() } });
        n++;
      }
    }
  }
  return n;
}

async function tellOwner(serverId: string, title: string, body: string, mail: Mailer) {
  const s = await db.server.findUnique({ where: { id: serverId }, select: { userId: true, hostname: true, label: true, user: { select: { email: true } } } });
  if (!s) return;
  const href = `/dashboard/servers/${serverId}?tab=mods`;
  const name = s.label || s.hostname;
  await db.notification.create({ data: { userId: s.userId, title: `${name}: ${title}`, body, href } }).catch(() => {});
  if (s.user?.email) await mail({ to: s.user.email, subject: `${name}: ${title}`, html: await emailHtml(`${name}: ${title}`, body, href, "Open the Mods tab"), userId: s.userId, kind: "mod_health" }).catch(() => false);
}

async function readLogSince(server: { id: string; osTemplate: { setupScript: string | null } } & Record<string, unknown>, since: Date): Promise<string> {
  const container = dockerContainerNameFrom(server.osTemplate.setupScript ?? "");
  if (!container || !CONTAINER_RE.test(container)) throw new Error("no container name");
  const cmd = `docker logs --since ${since.toISOString()} ${container} 2>&1 | tail -n 4000`;
  const r = await withServerSsh(server as never, (conn) => sshExec(conn, cmd, 30_000));
  return r.stdout;
}

/** Log reader; tests swap it (never SSH in tests). */
export let crashLogReader: (server: never, since: Date) => Promise<string> = readLogSince as never;
export function setCrashLogReader(fn: typeof crashLogReader) {
  crashLogReader = fn;
}

async function crashLoops(mail: Mailer, log: (s: string) => void): Promise<number> {
  const since = new Date(Date.now() - CRASH_WINDOW_MS);
  const recent = await db.serverMod.findMany({ where: { status: "INSTALLED", updatedAt: { gt: since }, mod: { source: CYRUS_SOURCE } }, select: { serverId: true }, distinct: ["serverId"], take: 50 });
  let n = 0;
  for (const { serverId } of recent) {
    const server = await db.server.findUnique({ where: { id: serverId }, include: { osTemplate: true, gamePlan: true, node: true, dedicatedIp: true, gameRuntime: true } });
    if (!server || server.status !== "RUNNING") continue;
    const rt = server.gameRuntime;
    if (!rt || !(DOWN_STATES.has(rt.state ?? "") || rt.containerState === "restarting")) continue;
    if (rt.intent === "stopped") continue;
    if ((await db.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } })) > 0) continue;
    const changed = await db.serverMod.findMany({ where: { serverId, updatedAt: { gt: since }, status: "INSTALLED" }, include: { mod: true }, orderBy: { updatedAt: "asc" } });
    if (!changed.some((c) => c.mod.source === CYRUS_SOURCE)) continue;
    const from = changed[0].updatedAt;
    let text: string;
    try {
      text = await crashLogReader(server as never, from);
    } catch (e) {
      log(`couldn't read the log of ${server.hostname}: ${(e as Error).message}`);
      continue;
    }
    const family = familyFor(server) ?? "minecraft";
    const mods = changed.map((c) => ({ name: c.mod.name, key: c.mod.sourceId ?? c.mod.name, fileName: c.fileName, row: c }));
    const v = judgeCrashLoop({ family, log: text, changed: mods, runtimeState: rt.state ?? null, containerState: rt.containerState ?? null });
    if (!v.crashLoop || !v.suspect) continue;
    const row = mods.find((m) => m.key === v.suspect!.key)!.row;
    if (row.mod.source !== CYRUS_SOURCE || !row.mod.sourceId) continue;
    const seen = await db.cyrusModSignal.findFirst({ where: { serverId, modId: row.modId, kind: "CRASH_LOOP", buildId: row.versionId, createdAt: { gt: since } } });
    if (seen) continue;
    await db.cyrusModSignal.create({ data: { serverId, modId: row.modId, rootBuildId: row.mod.sourceId, buildId: row.versionId, kind: "CRASH_LOOP", evidence: [v.why, ...v.evidence].join("\n").slice(0, 2000) } });
    const d = toggleDecision({ family, variant: server.gameVariant ?? null, mod: row.mod, engine: !!engineInstallerFor(family, row.mod.source) });
    let disabled = false;
    if (realChanges() && d.allowed && !d.needsAck) {
      const q = await enqueueModOp(serverId, row.modId, "disable", { userId: server.userId, slug: row.mod.slug });
      if (q.ok) {
        disabled = true;
        n++;
        await db.cyrusModSignal.create({ data: { serverId, modId: row.modId, rootBuildId: row.mod.sourceId, buildId: row.versionId, kind: "AUTO_DISABLED", evidence: `${v.why} We switched it off so the server can start.`.slice(0, 2000) } });
      }
    }
    log(`CRASH_LOOP ${row.mod.name} on ${server.hostname} (${v.why}) disabled=${disabled}`);
    await tellOwner(serverId, disabled ? `we switched off ${row.mod.name}` : `${row.mod.name} may be crashing your server`,
      disabled
        ? `${v.why} We switched it off (its config and data are kept) so the server can start again. Roll back to the previous version or switch it on again from the Mods tab.`
        : `${v.why} We didn't switch it off automatically. Open the Mods tab to switch it off or roll back.`,
      mail);
  }
  return n;
}

async function autoUpdates(log: (s: string) => void): Promise<number> {
  if (!realChanges()) return 0;
  const rows = await db.serverMod.findMany({ where: { status: "INSTALLED", autoUpdate: "AUTO", pinned: false, mod: { source: CYRUS_SOURCE } }, include: { mod: true }, take: 200 });
  let n = 0;
  const done = new Set<string>();
  for (const r of rows) {
    if (done.has(r.serverId) || !r.mod.sourceId) continue;
    const server = await db.server.findUnique({ where: { id: r.serverId }, include: { osTemplate: true, gamePlan: true } });
    if (!server || server.status !== "RUNNING") continue;
    const chain = await db.modBuild.findMany({ where: { OR: [{ id: r.mod.sourceId }, { rootBuildId: r.mod.sourceId }] }, orderBy: { createdAt: "asc" } });
    const head = chainHead(chain);
    if (!head || head.id === r.versionId) continue;
    if (!(await publicInstallAllowed(head, server.userId))) continue;
    if (await db.cyrusModSignal.findFirst({ where: { serverId: r.serverId, modId: r.modId, kind: { in: ["BROKEN", "CRASH_LOOP"] }, buildId: head.id } })) continue; // that version already misbehaved here
    const family = familyFor(server) ?? "minecraft";
    const support = supportFor(gameOfFamily(family));
    if (!support) continue;
    const compat = checkCompat({ support, serverVersion: await serverGameVersion(server), target: head.mcVersion, builtFor: succeededVersions(chain).map((b) => b.mcVersion) });
    if (compat.level === "block") continue;
    if ((await playersOnline(r.serverId, family)) !== 0) continue; // unknown or someone online: wait
    if ((await db.job.count({ where: { serverId: r.serverId, status: { in: ["QUEUED", "RUNNING"] } } })) > 0) continue;
    const q = await enqueueModOp(r.serverId, r.modId, "update", { userId: server.userId, slug: r.mod.slug }, { targetVersionId: head.id });
    if (q.ok) {
      done.add(r.serverId);
      n++;
      log(`auto-update ${r.mod.name} on ${server.hostname} -> ${head.id}`);
    }
  }
  return n;
}

/* ═══ creator warnings ═════════════════════════════════════════════════════ */

export async function cyrusCompatWatchSweep(opts: { force?: boolean; dryRun?: boolean; mailer?: Mailer; log?: (s: string) => void; now?: Date } = {}): Promise<{ chains: number; raised: number; resolved: number; notified: number; emailed: number; dryRun: boolean }> {
  const dry = opts.dryRun ?? (await getSettingBool("cyrus_compat_watch_dry_run", true));
  const out = { chains: 0, raised: 0, resolved: 0, notified: 0, emailed: 0, dryRun: dry };
  if (watchRunning) return out;
  if (!opts.force && !(await getSettingBool("cyrus_compat_watch_enabled", false))) return out;
  watchRunning = true;
  const log = opts.log ?? ((s: string) => console.log(`[cyrus-compat] ${s}`));
  const now = opts.now ?? new Date();
  const mail = opts.mailer ?? (await defaultMailer());
  try {
    const [installed, published] = await Promise.all([
      db.gameMod.findMany({ where: { source: CYRUS_SOURCE, installs: { some: { status: { in: ["INSTALLED", "DISABLED", "UPDATING"] } } } }, select: { id: true, sourceId: true } }),
      db.cyrusModPage.findMany({ where: { visibility: "PUBLIC", hiddenAt: null }, select: { rootBuildId: true } }),
    ]);
    const roots = [...new Set([...installed.map((g) => g.sourceId!).filter(Boolean), ...published.map((p) => p.rootBuildId)])].slice(0, 500);
    for (const root of roots) {
      out.chains++;
      const chain = await db.modBuild.findMany({ where: { OR: [{ id: root }, { rootBuildId: root }] }, orderBy: { createdAt: "asc" } });
      const ok = succeededVersions(chain);
      const head = chainHead(chain);
      if (!ok.length || !head) continue;
      const support = supportFor("minecraft")!; // ModBuild chains are Minecraft today
      const gm = installed.find((g) => g.sourceId === root);
      const installs = gm ? await db.serverMod.findMany({ where: { modId: gm.id, status: { in: ["INSTALLED", "DISABLED", "UPDATING"] } }, select: { serverId: true, server: { select: { id: true, gameConfig: true } } } }) : [];
      const withVersions = await Promise.all(installs.map(async (i) => ({ serverId: i.serverId, serverVersion: await serverGameVersion(i.server) })));
      const newest = ok[ok.length - 1];
      const broken = await db.cyrusModSignal.findMany({ where: { rootBuildId: root, kind: "BROKEN", buildId: newest.id, createdAt: { gt: new Date(now.getTime() - 7 * 86_400_000) } }, select: { serverId: true, evidence: true } });
      const erroring = new Set(broken.map((b) => b.serverId));
      const mismatch = new Set(broken.filter((b) => /NoSuchMethod|NoSuchField|NoClassDef|UnsupportedClassVersion|Unsupported API/.test(b.evidence ?? "")).map((b) => b.serverId));
      const facts: ChainFacts = {
        gameId: "minecraft",
        title: displayName(chain),
        builtFor: ok.map((b) => b.mcVersion),
        newestBuildId: newest.id,
        published: published.some((p) => p.rootBuildId === root),
        installs: withVersions,
        erroringServers: erroring.size,
        apiMismatchServers: mismatch.size,
      };
      const drafts = creatorAlertsFor(support, facts);
      const creator = chain[0].userId;
      const existing = await db.cyrusCreatorAlert.findMany({ where: { rootBuildId: root } });
      for (const d of drafts) {
        const ex = existing.find((e) => e.key === d.key);
        const row = ex
          ? await db.cyrusCreatorAlert.update({ where: { id: ex.id }, data: { lastSeenAt: now, servers: d.servers, title: d.title, body: d.body, targetVersion: d.targetVersion, buildable: d.buildable, dryRun: dry && ex.dryRun, resolvedAt: null } })
          : await db.cyrusCreatorAlert.create({ data: { userId: creator, rootBuildId: root, kind: d.kind, key: d.key, gameId: facts.gameId, targetVersion: d.targetVersion, buildable: d.buildable, title: d.title, body: d.body, servers: d.servers, dryRun: dry, firstSeenAt: now, lastSeenAt: now } });
        if (!ex) out.raised++;
        const emailsThisWeek = await db.cyrusCreatorAlert.count({ where: { userId: creator, emailedAt: { gt: new Date(now.getTime() - 7 * 86_400_000) } } });
        const decision = notifyDecision({ alert: row, dryRun: dry, emailsThisWeek, emailAllowed: await mayDeliverTo(creator, "cyrus_creator_alert", "email") });
        if (dry) {
          log(`DRY RUN would warn ${creator} (${facts.title}): ${d.title}`);
          continue;
        }
        const href = updateWithCyrusHref(head.id, d.buildable ? d.targetVersion : null);
        if (decision.inapp) {
          await db.notification.create({ data: { userId: creator, title: d.title, body: d.body, href: d.buildable || d.kind === "ERROR_REPORTS" ? href : "/dashboard/nxlabs/cyrus" } });
          await db.cyrusCreatorAlert.update({ where: { id: row.id }, data: { notifiedAt: now } });
          out.notified++;
        }
        if (decision.email) {
          const u = await db.user.findUnique({ where: { id: creator }, select: { email: true } });
          if (u?.email) {
            const sent = await mail({
              to: u.email, subject: d.title, userId: creator, kind: "cyrus_creator_alert",
              html: await emailHtml(d.title, d.body, d.buildable || d.kind === "ERROR_REPORTS" ? href : "/dashboard/nxlabs/cyrus", d.buildable ? `Update with Cyrus for ${d.targetVersion}` : "Open your mod"),
            }).catch(() => false);
            if (sent) {
              await db.cyrusCreatorAlert.update({ where: { id: row.id }, data: { emailedAt: now } });
              out.emailed++;
            }
          }
        }
      }
      // Anything this chain no longer triggers is resolved (the creator shipped, errors stopped).
      for (const e of existing) {
        if (!e.resolvedAt && !drafts.some((d) => d.key === e.key)) {
          await db.cyrusCreatorAlert.update({ where: { id: e.id }, data: { resolvedAt: now } });
          out.resolved++;
        }
      }
    }
  } finally {
    watchRunning = false;
  }
  log(`${out.chains} mods checked, ${out.raised} new, ${out.resolved} resolved, ${out.notified} notified, ${out.emailed} emailed${dry ? " (dry run)" : ""}`);
  return out;
}

