import type { Metadata } from "next";
import { requireCyrusAccess, cyrusMetadata } from "@/lib/cyrus-mods/gate";
import { backfillUserPages, listPageCards } from "@/lib/cyrus-mods/pages";
import { modBuilderUser } from "@/lib/modbuilder/access";
import { CyrusIndex } from "@/components/nx/labs/cyrus/CyrusIndex";
import { LabsTabs } from "@/components/nx/labs/LabsBits";
import "../labs.css";

export const dynamic = "force-dynamic";

export async function generateMetadata(): Promise<Metadata> {
  return cyrusMetadata("Cyrus Mods · NxLabs", "Open-source Paper plugins made with Cyrus.");
}

/** Portal NxLabs → Cyrus Mods. 404 for everyone outside lib/cyrus-mods/gate.ts. */
export default async function CyrusModsPortal({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  const { user, access } = await requireCyrusAccess();
  const q = String((await searchParams).q ?? "").slice(0, 60);
  if (user) await backfillUserPages(user.id).catch(() => 0); // builds made before pages existed
  const [cards, mb] = await Promise.all([listPageCards(user, { q, take: 60 }), modBuilderUser().catch(() => null)]);
  return (
    <div className="nxl-root mx-auto flex w-full max-w-[1320px] flex-col gap-6">
      <LabsTabs active="cyrus" installedCount={0} cyrus />
      <CyrusIndex cards={cards} base="/dashboard/nxlabs/cyrus" q={q} viewerId={user?.id ?? null} preview={access.preview} canBuild={!!mb} />
    </div>
  );
}
"use client";

import { CY_CTA } from "./cta";
import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { Icon } from "@/components/nx/Icon";
import { adminHideCyrusPage, refreshCyrusPage, setCyrusPageLicense, setCyrusPageVisibility } from "@/lib/actions-cyrus-mods";
import { CYRUS_LICENSES } from "@/lib/cyrus-mods/doc";
import type { PageView } from "@/lib/cyrus-mods/pages";

/**
 * Creator controls: publish (explicit, private by default), licence, regenerate.
 * Admin: hide/unhide the whole page. Shown only to the creator and admins.
 */
export function CyrusOwnerPanel({ p }: { p: PageView }) {
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const [confirmPublish, setConfirmPublish] = useState(false);
  const router = useRouter();
  const run = (fn: () => Promise<{ error?: string }>, ok: string) =>
    start(async () => {
      setMsg(null);
      const r = await fn().catch(() => ({ error: "Couldn't reach Nxeon." }));
      setMsg(r.error ? { ok: false, text: r.error } : { ok: true, text: ok });
      router.refresh();
    });
  const pub = p.visibility === "PUBLIC";
  return (
    <section className="rounded-[16px] border border-violet/35 bg-violet/[0.05] p-4" aria-label="Your mod page" data-testid="cyrus-owner-panel">
      <div className="flex flex-wrap items-start gap-4">

