cat > /tank/dev-worktrees/cyrus-v6-lifecycle/components/customer/cyrus/CreatorAlerts.tsx <<'EOF'
import { db } from "@/lib/db";
import { toAlertViews } from "@/lib/cyrus/lifecycle/server";
import { CreatorAlertCard } from "./CreatorAlertCard";

/**
 * "Your mod may need an update" for the signed-in creator (lib/cyrus/lifecycle/creator.ts,
 * raised by the compat watch). Server-rendered; nothing when there is nothing to say or on error.
 * `rootBuildId` narrows it to one mod (its NxLabs page).
 */
export async function CreatorAlerts({ userId, rootBuildId }: { userId: string; rootBuildId?: string }) {
  let alerts;
  try {
    const rows = await db.cyrusCreatorAlert.findMany({ where: { userId, dismissedAt: null, resolvedAt: null, dryRun: false, ...(rootBuildId ? { rootBuildId } : {}) }, orderBy: { lastSeenAt: "desc" }, take: 8 });
    alerts = await toAlertViews(rows);
  } catch {
    return null;
  }
  if (!alerts.length) return null;
  return (
    <section className="flex flex-col gap-2" aria-label="Mods that may need an update" data-testid="cyrus-creator-alerts">
      {alerts.map((a) => <CreatorAlertCard key={a.id} a={a} showMod={!rootBuildId} />)}
    </section>
  );
}
EOF
