"use client";

import { useState } from "react";
import Link from "next/link";
import { Icon } from "@/components/nx/Icon";
import { dismissCreatorAlert } from "@/lib/actions-cyrus-lifecycle";
import type { CreatorAlertView } from "@/lib/cyrus/lifecycle/server";

export function CreatorAlertCard({ a, showMod }: { a: CreatorAlertView; showMod: boolean }) {
  const [gone, setGone] = useState(false);
  const [busy, setBusy] = useState(false);
  if (gone) return null;
  const bad = a.kind === "ERROR_REPORTS";
  return (
    <div className={"flex flex-col gap-2.5 rounded-[14px] border p-3.5 sm:flex-row sm:items-center " + (bad ? "border-rose/40 bg-rose/[0.06]" : "border-amber/45 bg-amber/[0.06]")} data-testid="cyrus-creator-alert">
      <Icon name={bad ? "warntriangle" : "warncircle"} size={16} tone="inherit" className={"flex-none " + (bad ? "text-rose" : "text-amber")} />
      <div className="min-w-0 flex-1">
        <p className="text-[13px] font-bold text-tx">{a.title}</p>
        <p className="mt-0.5 text-[12px] leading-relaxed text-tx-dim">{a.body}</p>
        {showMod && a.pageSlug && <Link href={`/dashboard/nxlabs/cyrus/${a.pageSlug}`} className="mt-1 inline-block text-[11.5px] font-semibold text-violet hover:underline">{a.modTitle} page</Link>}
      </div>
      <div className="flex flex-none flex-wrap items-center gap-2">
        {a.updateHref && (
          <Link href={a.updateHref} className="nx-cta px-3.5 py-1.5 text-[12px]">
            {a.buildable && a.targetVersion ? `Update with Cyrus for ${a.targetVersion}` : "Fix it with Cyrus"}
          </Link>
        )}
        <button type="button" disabled={busy} onClick={async () => { setBusy(true); const r = await dismissCreatorAlert(a.id).catch(() => ({ error: "x" })); setBusy(false); if (!r.error) setGone(true); }}
          className="rounded-[10px] border border-rim-hi px-3 py-1.5 text-[12px] font-semibold text-tx-dim transition hover:text-tx disabled:opacity-50">
          Dismiss
        </button>
      </div>
    </div>
  );
}
EOF
