import { db } from "@/lib/db";
import { getSettingBool } from "@/lib/settings";
import { Badge, timeAgo } from "@/components/ui/primitives";
import { adminSetCyrusLifecycleSetting } from "@/lib/actions-cyrus-lifecycle";

/** /admin/cyrus-mods: the Cyrus lifecycle switches and what the compat watch raised (dry runs included). */
export async function CyrusLifecycleAdmin() {
  const [life, watch, dry, alerts, signals] = await Promise.all([
    getSettingBool("cyrus_lifecycle_enabled", false),
    getSettingBool("cyrus_compat_watch_enabled", false),
    getSettingBool("cyrus_compat_watch_dry_run", true),
    db.cyrusCreatorAlert.findMany({ orderBy: { lastSeenAt: "desc" }, take: 40 }).catch(() => []),
    db.cyrusModSignal.groupBy({ by: ["kind"], where: { createdAt: { gt: new Date(Date.now() - 7 * 86_400_000) } }, _count: { _all: true } }).catch(() => []),
  ]);
  const Toggle = ({ k, on, label }: { k: string; on: boolean; label: string }) => (
    <form action={adminSetCyrusLifecycleSetting} className="inline">
      <input type="hidden" name="key" value={k} />
      <input type="hidden" name="on" value={on ? "0" : "1"} />
      <button type="submit" className={on ? "btn-secondary text-xs" : "btn-primary text-xs"}>{label}</button>
    </form>
  );
  return (
    <div className="card mb-6" data-testid="cyrus-lifecycle-admin">
      <p className="text-sm font-semibold">Mod lifecycle (installed Cyrus mods)</p>
      <p className="mt-1 text-xs text-slate-400">Both sweeps live in the worker (worker/cyrus-lifecycle.ts) and do nothing while off. Server-side watch: Broken warnings from the game log, auto-disable after a crash loop right after an install, opt-in auto-updates (needs ENABLE_REAL_GAMEMODS=1; Broken also needs ENABLE_MOD_HEALTH=1). Creator warnings: &quot;your mod may need an update for Minecraft X&quot;; in dry run they are only recorded below.</p>
      <div className="mt-3 flex flex-wrap items-center gap-3 text-sm">
        <span>Server-side watch {life ? <Badge tone="green">on</Badge> : <Badge tone="brand">off</Badge>}</span>
        <Toggle k="cyrus_lifecycle_enabled" on={life} label={life ? "Turn off" : "Turn on"} />
        <span className="ml-4">Creator warnings {watch ? <Badge tone="green">on</Badge> : <Badge tone="brand">off</Badge>} {dry ? <Badge tone="brand">dry run</Badge> : <Badge tone="red">sending</Badge>}</span>
        <Toggle k="cyrus_compat_watch_enabled" on={watch} label={watch ? "Turn off" : "Turn on"} />
        <Toggle k="cyrus_compat_watch_dry_run" on={dry} label={dry ? "Start sending (leave dry run)" : "Back to dry run"} />
      </div>
      <p className="mt-3 text-xs text-slate-400">Last 7 days: {signals.length ? signals.map((s) => `${s._count._all} ${s.kind.toLowerCase().replace("_", " ")}`).join(" · ") : "no health signals"}</p>
      {alerts.length > 0 && (
        <div className="mt-3 overflow-x-auto">
          <table className="w-full text-left text-sm [&_td]:px-2 [&_th]:px-2">
            <thead className="text-xs text-slate-500"><tr><th className="py-1">Warning</th><th>Kind</th><th>Servers</th><th>State</th><th>Seen</th></tr></thead>
            <tbody>
              {alerts.map((a) => (
                <tr key={a.id} className="border-t border-slate-800/40 align-top">
                  <td className="max-w-[460px] py-1.5 text-xs"><b>{a.title}</b><div className="text-slate-400">{a.body}</div></td>
                  <td className="text-xs">{a.kind}</td>
                  <td>{a.servers}</td>
                  <td>{a.dryRun ? <Badge tone="brand">dry run</Badge> : a.resolvedAt ? <Badge tone="green">resolved</Badge> : a.dismissedAt ? <Badge tone="brand">dismissed</Badge> : a.emailedAt ? <Badge tone="green">emailed</Badge> : a.notifiedAt ? <Badge tone="green">notified</Badge> : <Badge tone="brand">open</Badge>}</td>
                  <td className="whitespace-nowrap text-xs">{timeAgo(a.lastSeenAt)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
