import { describe, it } from "node:test";
import assert from "node:assert/strict";
import minecraft from "../lib/cyrus/games/minecraft.ts";
import type { GameSupport } from "../lib/cyrus/games/support.ts";
import { checkCompat, compareVersions, outdatedReasons, ruleFor, versionLine } from "../lib/cyrus/lifecycle/compat.ts";
import { deriveLifecycle, nextState, TRANSITIONS, type LifecycleInput } from "../lib/cyrus/lifecycle/state.ts";
import { buildInstallPlan, confirmPlan, type PlanServer, type PlanMod } from "../lib/cyrus/lifecycle/install-plan.ts";
import { gameVersionFromLog, judgeCrashLoop, judgeCyrusLog } from "../lib/cyrus/lifecycle/logs.ts";
import { creatorAlertsFor, notifyDecision, updateWithCyrusHref, EMAILS_PER_CREATOR_PER_WEEK, type ChainFacts } from "../lib/cyrus/lifecycle/creator.ts";
import { buildableVersions, currentVersion, familyOfGame, gameOfFamily, supportFor } from "../lib/cyrus/lifecycle/support.ts";
import { MB_VERSIONS } from "../lib/modbuilder/types.ts";
import { configDir } from "../lib/mods/installers/cyrus.ts";

describe("versions", () => {
  it("compares numerically, pre-releases first, missing segments are 0", () => {
    assert.equal(compareVersions("1.21.11", "1.21.4"), 1);
    assert.equal(compareVersions("1.21", "1.21.0"), 0);
    assert.equal(compareVersions("26.1.2", "1.21.11"), 1);
    assert.equal(compareVersions("1.21.11-rc1", "1.21.11"), -1);
    assert.equal(compareVersions("Build 42", "Build 41.78"), 1);
    assert.equal(versionLine("1.21.4"), "1.21");
    assert.equal(versionLine("26.1.2"), "26.1");
  });
  it("matches exact rules and .x wildcards", () => {
    assert.equal(ruleFor(minecraft, "1.21.4")?.status, "supported");
    assert.equal(ruleFor(minecraft, "1.20.6")?.status, "unsupported");
    assert.equal(ruleFor(minecraft, "1.20")?.status, "unsupported");
    assert.equal(ruleFor(minecraft, "1.21.5"), null);
    assert.equal(ruleFor(minecraft, "26.3"), null);
  });
});

describe("Minecraft GameSupport stays in step with the build service", () => {
  it("buildable versions are exactly MB_VERSIONS, newest is current", () => {
    assert.deepEqual(buildableVersions(minecraft), [...MB_VERSIONS]);
    assert.equal(currentVersion(minecraft), MB_VERSIONS[0]);
    assert.equal(minecraft.install.side, "server");
    assert.equal(minecraft.install.hotReload, false);
  });
  it("registry and family mapping", () => {
    assert.equal(supportFor("minecraft")?.id, "minecraft");
    assert.equal(familyOfGame("zomboid"), "projectzomboid");
    assert.equal(gameOfFamily("minecraft"), "minecraft");
    assert.equal(supportFor("valheim"), null); // added when the game agent's branch merges
  });
});

describe("compat check", () => {
  const base = { support: minecraft, builtFor: ["1.21.4"] };
  it("exact match on a supported version is ok", () => {
    assert.equal(checkCompat({ ...base, serverVersion: "1.21.4", target: "1.21.4" }).level, "ok");
  });
  it("blocks unsupported and too-old servers", () => {
    const r = checkCompat({ ...base, serverVersion: "1.20.4", target: "1.21.4" });
    assert.equal(r.level, "block");
    assert.ok(r.reasons.some((x) => x.code === "server-unsupported"));
  });
  it("warns on legacy, unknown version, and built-for-older", () => {
    assert.equal(checkCompat({ ...base, serverVersion: "1.21.1", target: "1.21.1", builtFor: ["1.21.1"] }).reasons[0].code, "server-legacy");
    assert.equal(checkCompat({ ...base, serverVersion: null, target: "1.21.4" }).level, "warn");
    const older = checkCompat({ ...base, serverVersion: "1.21.8", target: "1.21.4" });
    assert.equal(older.level, "warn");
    assert.ok(older.newerThanTested);
  });
  it("built for a newer line than the server: block; same line: warn", () => {
    assert.equal(checkCompat({ ...base, serverVersion: "1.21.4", target: "1.21.11", builtFor: ["1.21.11"] }).level, "warn");
    const s = { ...minecraft, versions: [...minecraft.versions, { version: "26.1", status: "supported" as const }] };
    assert.equal(checkCompat({ support: s, serverVersion: "1.21.11", target: "26.1", builtFor: ["26.1"] }).level, "block");
  });
  it("a server ahead of anything Cyrus builds (Paper 26.x) warns, never blocks", () => {
    const r = checkCompat({ ...base, serverVersion: "26.3", target: "1.21.4" });
    assert.equal(r.level, "warn");
    assert.ok(r.reasons.some((x) => x.code === "server-ahead-of-cyrus"));
  });
  it("outdated reasons: game ahead (buildable or not) and a newer build", () => {
    const a = outdatedReasons({ support: minecraft, serverVersion: "1.21.11", builtFor: ["1.21.4"], installedTarget: "1.21.4", newerBuild: null });
    assert.equal(a[0].code, "game-ahead");
    assert.equal(a[0].targetVersion, "1.21.11");
    const b = outdatedReasons({ support: minecraft, serverVersion: "26.1", builtFor: ["1.21.11"], installedTarget: "1.21.11", newerBuild: "v3" });
    assert.equal(b[0].targetVersion, null);
    assert.match(b[0].text, /can't build for 26.1 yet/);
    assert.equal(b[1].code, "newer-build");
    assert.deepEqual(outdatedReasons({ support: minecraft, serverVersion: "1.21.4", builtFor: ["1.21.4"], installedTarget: "1.21.4", newerBuild: null }), []);
  });
});

describe("lifecycle state machine", () => {
  const I = (o: Partial<LifecycleInput>): LifecycleInput => ({ status: "INSTALLED", error: null, restartPending: false, broken: null, autoDisabled: null, outdated: [], rolledBack: false, ...o });
  it("resting states", () => {
    assert.equal(deriveLifecycle(I({})).state, "enabled");
    assert.equal(deriveLifecycle(I({ status: "DISABLED" })).state, "disabled");
    assert.equal(deriveLifecycle(I({ restartPending: true })).state, "pending_restart");
    assert.equal(deriveLifecycle(I({ status: "FAILED", error: "boom" })).state, "failed");
    assert.equal(deriveLifecycle(I({ broken: { evidence: "x", apiMismatch: false } })).state, "broken");
    assert.equal(deriveLifecycle(I({ outdated: [{ code: "newer-build", text: "v2 is out.", targetVersion: null }] })).state, "outdated");
  });
  it("in-flight wins, then failed > broken > disabled > pending restart > outdated", () => {
    assert.equal(deriveLifecycle(I({ status: "UPDATING", broken: { evidence: null, apiMismatch: false } })).state, "updating");
    assert.equal(deriveLifecycle(I({ broken: { evidence: null, apiMismatch: true }, restartPending: true, outdated: [{ code: "game-ahead", text: "t", targetVersion: null }] })).state, "broken");
    assert.equal(deriveLifecycle(I({ status: "DISABLED", broken: { evidence: null, apiMismatch: false } })).state, "disabled");
    assert.equal(deriveLifecycle(I({ restartPending: true, outdated: [{ code: "game-ahead", text: "t", targetVersion: null }] })).state, "pending_restart");
  });
  it("explains an auto-disable and a rolled-back update", () => {
    const d = deriveLifecycle(I({ status: "DISABLED", autoDisabled: { why: "the game kept crashing." } }));
    assert.match(d.notes[0], /We switched it off/);
    assert.deepEqual(d.actions, ["enable", "remove"]);
    const r = deriveLifecycle(I({ error: "disk full", rolledBack: true }));
    assert.equal(r.state, "enabled");
    assert.match(r.notes[0], /previous version was kept/);
  });
  it("API-mismatch breakage says out of date for this version", () => {
    assert.match(deriveLifecycle(I({ broken: { evidence: null, apiMismatch: true } })).notes[0], /out of date/);
  });
  it("transition table: every target is a known state; key paths", () => {
    const states = Object.keys(TRANSITIONS);
    for (const [, ev] of Object.entries(TRANSITIONS)) for (const to of Object.values(ev)) assert.ok(states.includes(to!));
    assert.equal(nextState("installing", "job_ok_restart"), "pending_restart");
    assert.equal(nextState("pending_restart", "restarted"), "enabled");
    assert.equal(nextState("enabled", "crash_loop"), "disabling");
    assert.equal(nextState("updating", "update_failed_rolled_back"), "enabled");
    assert.equal(nextState("disabled", "update"), null); // enable first (the queue only updates INSTALLED rows)
    assert.equal(nextState("broken", "log_clean"), "enabled");
  });
});

describe("install plan", () => {
  const srv = (o: Partial<PlanServer> = {}): PlanServer => ({ id: "s1", name: "SMP", sameGame: true, variantOk: true, running: true, version: "1.21.4", existing: null, ...o });
  const mod = (o: Partial<PlanMod> = {}): PlanMod => ({ name: "Coin Shop", buildId: "b2", target: "1.21.4", builtFor: ["1.21.4"], installable: true, safety: "pass", ...o });
  it("a clean install: no warnings, restart required, server only", () => {
    const p = buildInstallPlan(minecraft, mod(), srv());
    assert.equal(p.op, "install");
    assert.deepEqual(p.blockers, []);
    assert.deepEqual(p.warnings, []);
    assert.equal(p.restart, "required");
    assert.equal(p.players.needed, false);
    assert.deepEqual(p.steps.map((s) => s.id), ["check", "backup", "place", "load", "verify"]);
    assert.deepEqual(confirmPlan(p, []), { ok: true });
  });
  it("blocks: wrong variant, stopped, disabled row, safety block, unsupported version", () => {
    assert.ok(buildInstallPlan(minecraft, mod(), srv({ variantOk: false, variantNote: "Runs Vanilla" })).blockers.includes("Runs Vanilla"));
    assert.ok(buildInstallPlan(minecraft, mod(), srv({ running: false })).blockers.length);
    assert.ok(buildInstallPlan(minecraft, mod(), srv({ existing: { status: "DISABLED", buildId: "b1" } })).blockers[0].includes("switched off"));
    assert.ok(buildInstallPlan(minecraft, mod({ safety: "block" }), srv()).blockers.length);
    const p = buildInstallPlan(minecraft, mod(), srv({ version: "1.19.4" }));
    assert.equal(confirmPlan(p, ["anything"]).ok, false);
  });
  it("warnings must all be ticked (server-side gate)", () => {
    const p = buildInstallPlan(minecraft, mod({ safety: "warn" }), srv({ version: "1.21.8" }));
    assert.deepEqual(p.warnings.map((w) => w.id).sort(), ["built-for-older", "safety-warn"]);
    assert.equal(confirmPlan(p, ["built-for-older"]).ok, false);
    assert.equal(confirmPlan(p, ["built-for-older", "safety-warn"]).ok, true);
  });
  it("update vs already there", () => {
    assert.equal(buildInstallPlan(minecraft, mod(), srv({ existing: { status: "INSTALLED", buildId: "b1" } })).op, "update");
    assert.equal(buildInstallPlan(minecraft, mod(), srv({ existing: { status: "INSTALLED", buildId: "b2" } })).op, "none");
  });
  it("a game where players need the mod too gets a must-tick 'players must also install this' step", () => {
    const both: GameSupport = { ...minecraft, id: "valheim", name: "Valheim", install: { ...minecraft.install, side: "both", clientNote: "Install it with r2modman, same version as the server.", packaging: "dll", serverPath: "BepInEx/plugins/" } };
    const p = buildInstallPlan(both, mod(), srv());
    assert.equal(p.players.needed, true);
    assert.ok(p.warnings.some((w) => w.id === "players-must-install" && /r2modman/.test(w.text)));
    assert.ok(p.steps.some((s) => s.id === "players"));
  });
  it("a game with no real installer yet is honest about it", () => {
    assert.match(buildInstallPlan(minecraft, mod({ installable: false }), srv()).blockers[0], /aren't available yet/);
  });
});

/* Sample Paper logs, written in Paper's own line format. */
const BOOT = `[12:00:01] [ServerMain/INFO]: Starting minecraft server version 1.21.4
[12:00:02] [Server thread/INFO]: Loading libraries, please wait...`;
const OK_LOG = `${BOOT}
[12:00:05] [Server thread/INFO]: [CoinShop] Enabling CoinShop v1.2.0
[12:00:09] [Server thread/INFO]: Done (8.123s)! For help, type "help"`;
const RUNTIME_ERR = `${OK_LOG}
[12:05:00] [Server thread/ERROR]: Could not pass event PlayerJoinEvent to CoinShop v1.2.0
java.lang.NullPointerException: Cannot invoke "Object.toString()"`;
const MISMATCH = `${BOOT}
[12:00:05] [Server thread/INFO]: [QuestBoard] Enabling QuestBoard v2.0.0
[12:00:05] [Server thread/ERROR]: Error occurred while enabling QuestBoard v2.0.0 (Is it up to date?)
java.lang.NoSuchMethodError: 'org.bukkit.inventory.ItemStack org.bukkit.inventory.meta.ItemMeta.foo()'
	at net.example.questboard.QuestBoard.onEnable(QuestBoard.java:41)
[12:00:09] [Server thread/INFO]: Done (8.0s)! For help, type "help"`;

describe("log reading", () => {
  const coin = { name: "Coin Shop", key: "mbcoin", fileName: "CoinShop-1.2.0.jar" };
  const quest = { name: "Quest Board", key: "mbquest", fileName: "QuestBoard-2.0.0.jar" };
  it("game version from the LAST boot", () => {
    assert.equal(gameVersionFromLog("minecraft", `${BOOT}\n[..] Starting minecraft server version 1.21.8`), "1.21.8");
    assert.equal(gameVersionFromLog("valheim", BOOT), null);
  });
  it("clean load", () => {
    const [v] = judgeCyrusLog({ family: "minecraft", variant: "paper", mods: [coin], log: OK_LOG });
    assert.equal(v.status, "loaded");
  });
  it("runtime error naming the plugin = broken, not a mismatch", () => {
    const [v] = judgeCyrusLog({ family: "minecraft", variant: "paper", mods: [coin], log: RUNTIME_ERR });
    assert.equal(v.status, "broken");
    assert.equal(v.apiMismatch, false);
    assert.match(v.evidence[0], /Could not pass event/);
  });
  it("NoSuchMethodError right after the plugin's line = broken + API mismatch (out of date)", () => {
    const [c, q] = judgeCyrusLog({ family: "minecraft", variant: "paper", mods: [coin, quest], log: MISMATCH });
    assert.equal(q.status, "broken");
    assert.equal(q.apiMismatch, true);
    assert.notEqual(c.status, "broken"); // never blame a mod the errors don't name
  });
  it("crash loop: several boots, never ready; pinned on the named mod, or on the only change", () => {
    const loop = [BOOT, "[12:00:05] [Server thread/ERROR]: Error occurred while enabling QuestBoard v2.0.0", "java.lang.NoSuchMethodError: x", "Exception in server tick loop", BOOT, "[12:01:05] [Server thread/ERROR]: Error occurred while enabling QuestBoard v2.0.0", BOOT].join("\n");
    const v = judgeCrashLoop({ family: "minecraft", log: loop, changed: [coin, quest], runtimeState: "crashed", containerState: "restarting" });
    assert.equal(v.crashLoop, true);
    assert.equal(v.starts, 3);
    assert.equal(v.suspect?.key, "mbquest");
    const only = judgeCrashLoop({ family: "minecraft", log: [BOOT, "Exception in server tick loop", BOOT].join("\n"), changed: [coin], runtimeState: null, containerState: "restarting" });
    assert.equal(only.suspect?.key, "mbcoin");
    const two = judgeCrashLoop({ family: "minecraft", log: [BOOT, "Exception in server tick loop", BOOT].join("\n"), changed: [coin, quest], runtimeState: null, containerState: null });
    assert.equal(two.crashLoop, true);
    assert.equal(two.suspect, null); // two changes, none named: nobody is auto-disabled
  });
  it("not a crash loop once the game finished starting", () => {
    const v = judgeCrashLoop({ family: "minecraft", log: `${BOOT}\n${OK_LOG}`, changed: [coin], runtimeState: "online", containerState: "running" });
    assert.equal(v.crashLoop, false);
  });
});

describe("creator warnings", () => {
  const facts = (o: Partial<ChainFacts> = {}): ChainFacts => ({ gameId: "minecraft", title: "Frost Axe", builtFor: ["1.21.4"], newestBuildId: "b3", published: true, installs: [], erroringServers: 0, apiMismatchServers: 0, ...o });
  it("new version Cyrus can build: one warning with a buildable target", () => {
    const a = creatorAlertsFor(minecraft, facts());
    assert.equal(a.length, 1);
    assert.equal(a[0].key, "NEW_GAME_VERSION:minecraft:1.21.11");
    assert.equal(a[0].buildable, true);
    assert.match(a[0].title, /may need an update for Minecraft 1\.21\.11/);
  });
  it("nobody uses it (private, no installs): no warning", () => {
    assert.deepEqual(creatorAlertsFor(minecraft, facts({ published: false })), []);
  });
  it("already on the newest version: nothing", () => {
    assert.deepEqual(creatorAlertsFor(minecraft, facts({ builtFor: ["1.21.4", "1.21.11"] })), []);
  });
  it("servers ahead on 26.x: warning without a build button (Cyrus can't build 26.x yet)", () => {
    const a = creatorAlertsFor(minecraft, facts({ builtFor: ["1.21.11"], installs: [{ serverId: "a", serverVersion: "26.1.2" }, { serverId: "b", serverVersion: "1.21.11" }] }));
    assert.equal(a.length, 1);
    assert.equal(a[0].kind, "SERVERS_AHEAD");
    assert.equal(a[0].buildable, false);
    assert.equal(a[0].targetVersion, null);
    assert.equal(a[0].key, "SERVERS_AHEAD:minecraft:26.1");
  });
  it("errors on 2+ servers, mostly API mismatches: rebuild for current", () => {
    const one = creatorAlertsFor(minecraft, facts({ builtFor: ["1.21.11"], erroringServers: 1, apiMismatchServers: 1 }));
    assert.deepEqual(one, []);
    const a = creatorAlertsFor(minecraft, facts({ builtFor: ["1.21.11"], erroringServers: 3, apiMismatchServers: 2 }));
    assert.equal(a[0].kind, "ERROR_REPORTS");
    assert.equal(a[0].key, "ERROR_REPORTS:b3");
    assert.equal(a[0].buildable, true);
  });
  it("rate limit: dry run tells nobody; in-app once; email once, max per week, and only when allowed", () => {
    const fresh = { notifiedAt: null, emailedAt: null, dismissedAt: null, resolvedAt: null };
    assert.deepEqual(notifyDecision({ alert: fresh, dryRun: true, emailsThisWeek: 0, emailAllowed: true }), { inapp: false, email: false, why: "dry run" });
    assert.equal(notifyDecision({ alert: fresh, dryRun: false, emailsThisWeek: 0, emailAllowed: true }).email, true);
    assert.equal(notifyDecision({ alert: fresh, dryRun: false, emailsThisWeek: EMAILS_PER_CREATOR_PER_WEEK, emailAllowed: true }).email, false);
    assert.equal(notifyDecision({ alert: fresh, dryRun: false, emailsThisWeek: 0, emailAllowed: false }).email, false);
    const done = { ...fresh, notifiedAt: new Date(), emailedAt: new Date() };
    assert.deepEqual(notifyDecision({ alert: done, dryRun: false, emailsThisWeek: 0, emailAllowed: true }).inapp, false);
    assert.equal(notifyDecision({ alert: { ...fresh, dismissedAt: new Date() }, dryRun: false, emailsThisWeek: 0, emailAllowed: true }).inapp, false);
  });
  it("Update with Cyrus deep link preselects the version", () => {
    assert.equal(updateWithCyrusHref("mb123", "1.21.11"), "/dashboard/cyrus/mb123?retarget=1.21.11");
    assert.equal(updateWithCyrusHref("mb123", null), "/dashboard/cyrus/mb123");
  });
});

describe("config backup folder", () => {
  it("never backs up plugins/ itself", () => {
    assert.equal(configDir("CoinShop"), "CoinShop");
    assert.equal(configDir("../.."), null);
    assert.equal(configDir(null), null);
  });
});

