    assert.equal(supportFor("valheim"), null); // added when the game agent's branch merges
  });
});

describe("compat check", () => {
  const base = { support: minecraft, builtFor: ["1.21.4"] };
  it("exact match on a supported version is ok", () => {
    assert.equal(checkCompat({ ...base, serverVersion: "1.21.4", target: "1.21.4" }).level, "ok");
  });
  it("blocks unsupported and too-old servers", () => {
    const r = checkCompat({ ...base, serverVersion: "1.20.4", target: "1.21.4" });
    assert.equal(r.level, "block");
    assert.ok(r.reasons.some((x) => x.code === "server-unsupported"));
  });
  it("warns on legacy, unknown version, and built-for-older", () => {
    assert.equal(checkCompat({ ...base, serverVersion: "1.21.1", target: "1.21.1", builtFor: ["1.21.1"] }).reasons[0].code, "server-legacy");
    assert.equal(checkCompat({ ...base, serverVersion: null, target: "1.21.4" }).level, "warn");
    const older = checkCompat({ ...base, serverVersion: "1.21.8", target: "1.21.4" });
    assert.equal(older.level, "warn");
    assert.ok(older.newerThanTested);
  });
  it("built for a newer line than the server: block; same line: warn", () => {
    assert.equal(checkCompat({ ...base, serverVersion: "1.21.4", target: "1.21.11", builtFor: ["1.21.11"] }).level, "warn");
    const s = { ...minecraft, versions: [...minecraft.versions, { version: "26.1", status: "supported" as const }] };
    assert.equal(checkCompat({ support: s, serverVersion: "1.21.11", target: "26.1", builtFor: ["26.1"] }).level, "block");
  });
  it("a server ahead of anything Cyrus builds (Paper 26.x) warns, never blocks", () => {
    const r = checkCompat({ ...base, serverVersion: "26.3", target: "1.21.4" });
    assert.equal(r.level, "warn");
    assert.ok(r.reasons.some((x) => x.code === "server-ahead-of-cyrus"));
  });
  it("outdated reasons: game ahead (buildable or not) and a newer build", () => {
    const a = outdatedReasons({ support: minecraft, serverVersion: "1.21.11", builtFor: ["1.21.4"], installedTarget: "1.21.4", newerBuild: null });
    assert.equal(a[0].code, "game-ahead");
    assert.equal(a[0].targetVersion, "1.21.11");
    const b = outdatedReasons({ support: minecraft, serverVersion: "26.1", builtFor: ["1.21.11"], installedTarget: "1.21.11", newerBuild: "v3" });
    assert.equal(b[0].targetVersion, null);
    assert.match(b[0].text, /can't build for 26.1 yet/);
    assert.equal(b[1].code, "newer-build");
    assert.deepEqual(outdatedReasons({ support: minecraft, serverVersion: "1.21.4", builtFor: ["1.21.4"], installedTarget: "1.21.4", newerBuild: null }), []);
  });
});

describe("lifecycle state machine", () => {
  const I = (o: Partial<LifecycleInput>): LifecycleInput => ({ status: "INSTALLED", error: null, restartPending: false, broken: null, autoDisabled: null, outdated: [], rolledBack: false, ...o });
  it("resting states", () => {
    assert.equal(deriveLifecycle(I({})).state, "enabled");
    assert.equal(deriveLifecycle(I({ status: "DISABLED" })).state, "disabled");
    assert.equal(deriveLifecycle(I({ restartPending: true })).state, "pending_restart");
    assert.equal(deriveLifecycle(I({ status: "FAILED", error: "boom" })).state, "failed");
    assert.equal(deriveLifecycle(I({ broken: { evidence: "x", apiMismatch: false } })).state, "broken");
    assert.equal(deriveLifecycle(I({ outdated: [{ code: "newer-build", text: "v2 is out.", targetVersion: null }] })).state, "outdated");
  });
  it("in-flight wins, then failed > broken > disabled > pending restart > outdated", () => {
    assert.equal(deriveLifecycle(I({ status: "UPDATING", broken: { evidence: null, apiMismatch: false } })).state, "updating");
    assert.equal(deriveLifecycle(I({ broken: { evidence: null, apiMismatch: true }, restartPending: true, outdated: [{ code: "game-ahead", text: "t", targetVersion: null }] })).state, "broken");
    assert.equal(deriveLifecycle(I({ status: "DISABLED", broken: { evidence: null, apiMismatch: false } })).state, "disabled");
    assert.equal(deriveLifecycle(I({ restartPending: true, outdated: [{ code: "game-ahead", text: "t", targetVersion: null }] })).state, "pending_restart");
  });
  it("explains an auto-disable and a rolled-back update", () => {
    const d = deriveLifecycle(I({ status: "DISABLED", autoDisabled: { why: "the game kept crashing." } }));
    assert.match(d.notes[0], /We switched it off/);
    assert.deepEqual(d.actions, ["enable", "remove"]);
    const r = deriveLifecycle(I({ error: "disk full", rolledBack: true }));
    assert.equal(r.state, "enabled");
    assert.match(r.notes[0], /previous version was kept/);
  });
  it("API-mismatch breakage says out of date for this version", () => {
    assert.match(deriveLifecycle(I({ broken: { evidence: null, apiMismatch: true } })).notes[0], /out of date/);
  });
  it("transition table: every target is a known state; key paths", () => {
    const states = Object.keys(TRANSITIONS);
    for (const [, ev] of Object.entries(TRANSITIONS)) for (const to of Object.values(ev)) assert.ok(states.includes(to!));
    assert.equal(nextState("installing", "job_ok_restart"), "pending_restart");
    assert.equal(nextState("pending_restart", "restarted"), "enabled");
    assert.equal(nextState("enabled", "crash_loop"), "disabling");
    assert.equal(nextState("updating", "update_failed_rolled_back"), "enabled");
    assert.equal(nextState("disabled", "update"), null); // enable first (the queue only updates INSTALLED rows)
    assert.equal(nextState("broken", "log_clean"), "enabled");
  });
});

describe("install plan", () => {
  const srv = (o: Partial<PlanServer> = {}): PlanServer => ({ id: "s1", name: "SMP", sameGame: true, variantOk: true, running: true, version: "1.21.4", existing: null, ...o });
  const mod = (o: Partial<PlanMod> = {}): PlanMod => ({ name: "Coin Shop", buildId: "b2", target: "1.21.4", builtFor: ["1.21.4"], installable: true, safety: "pass", ...o });
  it("a clean install: no warnings, restart required, server only", () => {
    const p = buildInstallPlan(minecraft, mod(), srv());
    assert.equal(p.op, "install");
    assert.deepEqual(p.blockers, []);
    assert.deepEqual(p.warnings, []);
    assert.equal(p.restart, "required");
    assert.equal(p.players.needed, false);
    assert.deepEqual(p.steps.map((s) => s.id), ["check", "backup", "place", "load", "verify"]);
    assert.deepEqual(confirmPlan(p, []), { ok: true });
  });
  it("blocks: wrong variant, stopped, disabled row, safety block, unsupported version", () => {
    assert.ok(buildInstallPlan(minecraft, mod(), srv({ variantOk: false, variantNote: "Runs Vanilla" })).blockers.includes("Runs Vanilla"));
    assert.ok(buildInstallPlan(minecraft, mod(), srv({ running: false })).blockers.length);
    assert.ok(buildInstallPlan(minecraft, mod(), srv({ existing: { status: "DISABLED", buildId: "b1" } })).blockers[0].includes("switched off"));
    assert.ok(buildInstallPlan(minecraft, mod({ safety: "block" }), srv()).blockers.length);
    const p = buildInstallPlan(minecraft, mod(), srv({ version: "1.19.4" }));
    assert.equal(confirmPlan(p, ["anything"]).ok, false);
  });
  it("warnings must all be ticked (server-side gate)", () => {
    const p = buildInstallPlan(minecraft, mod({ safety: "warn" }), srv({ version: "1.21.8" }));
    assert.deepEqual(p.warnings.map((w) => w.id).sort(), ["built-for-older", "safety-warn"]);
    assert.equal(confirmPlan(p, ["built-for-older"]).ok, false);
    assert.equal(confirmPlan(p, ["built-for-older", "safety-warn"]).ok, true);
  });
  it("update vs already there", () => {
    assert.equal(buildInstallPlan(minecraft, mod(), srv({ existing: { status: "INSTALLED", buildId: "b1" } })).op, "update");
    assert.equal(buildInstallPlan(minecraft, mod(), srv({ existing: { status: "INSTALLED", buildId: "b2" } })).op, "none");
  });
  it("a game where players need the mod too gets a must-tick 'players must also install this' step", () => {
    const both: GameSupport = { ...minecraft, id: "valheim", name: "Valheim", install: { ...minecraft.install, side: "both", clientNote: "Install it with r2modman, same version as the server.", packaging: "dll", serverPath: "BepInEx/plugins/" } };
    const p = buildInstallPlan(both, mod(), srv());
    assert.equal(p.players.needed, true);
    assert.ok(p.warnings.some((w) => w.id === "players-must-install" && /r2modman/.test(w.text)));
    assert.ok(p.steps.some((s) => s.id === "players"));
  });
  it("a game with no real installer yet is honest about it", () => {
    assert.match(buildInstallPlan(minecraft, mod({ installable: false }), srv()).blockers[0], /aren't available yet/);
  });
});

