  it("crash loop: several boots, never ready; pinned on the named mod, or on the only change", () => {
    const loop = [BOOT, "[12:00:05] [Server thread/ERROR]: Error occurred while enabling QuestBoard v2.0.0", "java.lang.NoSuchMethodError: x", "Exception in server tick loop", BOOT, "[12:01:05] [Server thread/ERROR]: Error occurred while enabling QuestBoard v2.0.0", BOOT].join("\n");
