import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { mkdtempSync, writeFileSync, existsSync, readdirSync, mkdirSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

/**
 * Mock-driven END-TO-END of the Cyrus mod lifecycle against a THROWAWAY Postgres and the
 * SANDBOX guest filesystem (lib/mods/guest-fs.ts LocalGuestFs: a temp folder stands in for the
 * server's disk). Real engine, real worker functions (GAME_MOD_SYNC, the lifecycle sweeps), real
 * DB writes; no SSH, no network, no email (a fake mailer records what would be sent).
 *
 * Opt-in and fail-closed: runs only when CYRUS_LIFECYCLE_DB_TEST=1 and DATABASE_URL is a node-2
 * agent database (127.0.0.1:5433/wt_*). Schema first: `devhost db push`.
 *   devhost run --lock -- env CYRUS_LIFECYCLE_DB_TEST=1 npx tsx --test test/cyrus-lifecycle-db.test.ts
 */
const url = process.env.DATABASE_URL ?? "";
const safe = process.env.CYRUS_LIFECYCLE_DB_TEST === "1" && /^postgres(ql)?:\/\/[^@]*@127\.0\.0\.1:5433\/wt_[a-z0-9_]+(\?.*)?$/.test(url);
const skip = safe ? false : "set CYRUS_LIFECYCLE_DB_TEST=1 with a node-2 throwaway DATABASE_URL to run";

const guestDir = mkdtempSync(path.join(tmpdir(), "cyrus-lc-guest-"));
const jarDir = mkdtempSync(path.join(tmpdir(), "cyrus-lc-jars-"));
process.env.NXEON_SANDBOX = "1";
process.env.NXEON_SANDBOX_GUEST_DIR = guestDir;

type Db = typeof import("../lib/db.ts")["db"];
let db: Db;
let W: typeof import("../worker/game-mods.ts");
let LC: typeof import("../worker/cyrus-lifecycle.ts");
let S: typeof import("../lib/cyrus/lifecycle/server.ts");
let Q: typeof import("../lib/mods/queue.ts");
let I: typeof import("../lib/modbuilder/install.ts");
let L: typeof import("../lib/cyrus/lifecycle/logs.ts");

const uniq = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
const ids = { user: "", server: "", mod: "" };
const sent: { to: string; subject: string; kind: string }[] = [];
const mailer = async (o: { to: string; subject: string; kind: string }) => { sent.push(o); return true; };
const quiet = () => {};

async function mkBuild(id: string, n: number, mcVersion: string, extra: Record<string, unknown> = {}) {
  const bytes = Buffer.from(`fake jar ${id} v${n}`);
  const jarPath = path.join(jarDir, `${id}.jar`);
  writeFileSync(jarPath, bytes);
  return db.modBuild.create({
    data: {
      id, userId: ids.user, prompt: "A coin shop with /pay and a chest menu", status: "succeeded", mcVersion, pluginName: "CoinShop", version: `1.${n - 1}.0`,
      rootBuildId: `${uniq}a`, baseBuildId: n > 1 ? `${uniq}a` : null, jarName: `CoinShop-1.${n - 1}.0.jar`, jarPath, jarSize: bytes.length, jarSha256: createHash("sha256").update(bytes).digest("hex"),
      result: { summary: { tagline: "Coins", text: "Coins for kills", changes: n > 1 ? `Version ${n}: faster shop menu` : null }, safety: { verdict: "pass" } },
      createdAt: new Date(Date.now() - (10 - n) * 60_000), finishedAt: new Date(), ...extra,
    } as never,
  });
}

/** Stand-in for the worker loop: run the queued GAME_MOD_SYNC and mark it DONE. */
async function runJobs() {
  const jobs = await db.job.findMany({ where: { serverId: ids.server, status: "QUEUED", type: "GAME_MOD_SYNC" }, orderBy: { createdAt: "asc" } });
  for (const j of jobs) {
    await W.gameModSync(j);
    await db.job.update({ where: { id: j.id }, data: { status: "DONE" } });
  }
  return jobs.length;
}
const sm = () => db.serverMod.findUnique({ where: { serverId_modId: { serverId: ids.server, modId: ids.mod } } });
const state = async () => (await S.lifecycleForServer(ids.server))[0]?.view;
const guest = (p: string) => path.join(guestDir, ids.server, p);

describe("Cyrus lifecycle end to end (sandbox guest, throwaway DB)", { skip }, () => {
  before(async () => {
    ({ db } = await import("../lib/db.ts"));
    W = await import("../worker/game-mods.ts");
    LC = await import("../worker/cyrus-lifecycle.ts");
    S = await import("../lib/cyrus/lifecycle/server.ts");
    Q = await import("../lib/mods/queue.ts");
    I = await import("../lib/modbuilder/install.ts");
    L = await import("../lib/cyrus/lifecycle/logs.ts");
    const user = await db.user.create({ data: { email: `lc-${uniq}@nxeon.test`, passwordHash: "x", name: "LC Creator", role: "CUSTOMER", emailVerifiedAt: new Date() } as never });
    ids.user = user.id;
    const plan = await db.plan.upsert({ where: { slug: "lctest" }, create: { slug: "lctest", name: "t", cpuCores: 1, ramMB: 1024, diskGB: 10, priceCents: 1 }, update: {} });
    const os = await db.osTemplate.upsert({ where: { slug: "lctest-mc" }, create: { slug: "lctest-mc", name: "Minecraft", vmid: 1, family: "minecraft" }, update: {} });
    const gp = await db.gamePlan.create({ data: { gameFamily: "minecraft", name: "t", ramMB: 4096, diskGB: 10, priceCents: 1, basePlanId: plan.id } as never });
    const server = await db.server.create({ data: { name: `lc-${uniq}`, hostname: `lc-${uniq}.test`, userId: user.id, planId: plan.id, osTemplateId: os.id, gamePlanId: gp.id, status: "RUNNING", gameVariant: "paper", gameConfig: { VERSION: "1.21.4" } } as never });
    ids.server = server.id;
    await mkBuild(`${uniq}a`, 1, "1.21.4");
  });

  after(async () => {
    if (!safe) return;
    await db.cyrusCreatorAlert.deleteMany({ where: { userId: ids.user } }).catch(() => {});
    await db.cyrusModSignal.deleteMany({ where: { serverId: ids.server } }).catch(() => {});
    await db.server.deleteMany({ where: { id: ids.server } }).catch(() => {});
    await db.modBuild.deleteMany({ where: { userId: ids.user } }).catch(() => {});
    await db.notification.deleteMany({ where: { userId: ids.user } }).catch(() => {});
    rmSync(guestDir, { recursive: true, force: true });
    rmSync(jarDir, { recursive: true, force: true });
  });

  it("install: plan is clean, the jar lands in plugins/, state Pending restart", async () => {
    const b = await db.modBuild.findUniqueOrThrow({ where: { id: `${uniq}a` } });
    const { plans } = await S.installPlansFor(b, ids.user);
    const p = plans.find((x) => x.server.id === ids.server)!;
    assert.equal(p.plan.op, "install");
    assert.deepEqual(p.plan.blockers, []);
    assert.deepEqual(p.plan.warnings, []);
    const r = await I.installBuildToServer(b, ids.user, ids.server, { waitMs: 0 });
    assert.ok(r.ok, JSON.stringify(r));
    ids.mod = (r as { modId: string }).modId;
    assert.equal(await runJobs(), 1);
    const row = await sm();
    assert.equal(row?.status, "INSTALLED");
    assert.equal(row?.versionId, `${uniq}a`);
    assert.ok(existsSync(guest("opt/mc/plugins/CoinShop-1.0.0.jar")));
    assert.equal((await state())?.state, "pending_restart");
  });

